// GCSE History practice papers: Edexcel 1HI0 (Papers 1-3) and AQA 8145 (Papers 1-2).
// Every source and interpretation below is a practice text written for this app (clearly labelled), modelled on the
// kinds of evidence the boards use. Question types, marks and timings follow the boards' sample assessment materials.
import type { ExamQuestion } from '../types';
import { examQ } from '../dsl';
import type { MockPaper, MockSection, MockTest, WrittenQ } from './types';

const w = (n: string, eq: ExamQuestion, topicId: string, lines = 14): WrittenQ => ({ kind: 'written', n, marks: eq.marks, eq, topicId, lines });
const P = (label: string, intro: string, text: string, real = false) => `**${label}** – ${intro} *(${real ? 'Adapted from the original source.' : 'Practice source written for this app.'})*\n\n> ${text.trim().split('\n').join('\n> ')}`;

// ---------------- Generic level descriptors ----------------
const lv = (bands: [number, number, string][], ind: string, extra: string[] = []) => [
  ...bands.map(([lo, hi, d], i) => `Level ${bands.length - i} (${lo}-${hi} marks): ${d}`),
  ...extra,
  `Indicative content: ${ind}`,
];
const SPAG = [
  'SPaG High performance (4 marks): spells and punctuates with consistent accuracy; consistently uses rules of grammar with effective control of meaning; uses a wide range of specialist terms as appropriate.',
  'SPaG Intermediate performance (2-3 marks): spells and punctuates with considerable accuracy; uses rules of grammar with general control of meaning; uses a good range of specialist terms.',
  'SPaG Threshold performance (1 mark): spells and punctuates with reasonable accuracy; uses rules of grammar with some control of meaning; uses a limited range of specialist terms.',
];
const features = (f: [string, string][]) => [
  'Identifies a first valid feature (1)', 'Gives supporting information for that feature (1)', 'Identifies a second valid feature (1)', 'Gives supporting information for the second feature (1)',
  `Valid features and support include: ${f.map(([a, b]) => `${a} – ${b}`).join('; ')}.`,
];
const inference = (inf: string) => ['First inference from the source (1)', 'Supporting detail quoted or paraphrased from the source (1)', 'Second inference (1)', 'Supporting detail for the second inference (1)', `Valid inferences include: ${inf}`];

// Edexcel descriptors
const ED_WHY = (ind: string) => lv([
  [10, 12, 'An analytical explanation directed consistently at the question; lines of reasoning are coherent, logically structured and show causation. Accurate and relevant information shows wide-ranging knowledge and understanding, including points beyond the stimulus.'],
  [7, 9, 'An explanation showing some analysis, generally directed at the question; mainly coherent lines of reasoning. Accurate and relevant information shows good knowledge.'],
  [4, 6, 'A simple or generalised explanation with limited analysis; some development and organisation. Some accurate and relevant information.'],
  [1, 3, 'A simple or generalised answer lacking development; basic information.'],
], ind, ['Maximum 8 marks for answers that do not go beyond the two stimulus points.']);
const ED_HOWFAR = (ind: string, spag = true) => lv([
  [13, 16, 'An analytical explanation directed consistently at the question; coherent, logically structured reasoning. Accurate, relevant information shows wide-ranging knowledge, including beyond the stimulus. Criteria for the judgement are justified and the overall judgement is fully substantiated.'],
  [9, 12, 'An explanation showing some analysis, generally directed at the question. Accurate and relevant information shows good knowledge. Criteria for the judgement are stated and the judgement is partly substantiated.'],
  [5, 8, 'A simple or generalised explanation with limited analysis. Some accurate and relevant information. An overall judgement is given but its justification is asserted or insecure.'],
  [1, 4, 'A simple or generalised answer lacking development; basic information. A judgement may be asserted without support.'],
], ind, ['Maximum 11 marks for answers that do not go beyond the two stimulus points.', ...(spag ? SPAG : [])]);
const ED_USE = (ind: string) => lv([
  [6, 8, 'Judgements on source utility for the specified enquiry are given with developed reasoning that takes account of how provenance affects usefulness. Sources are analysed to support reasoning about their usefulness. Relevant contextual knowledge is used directly in the evaluation.'],
  [3, 5, 'Judgements on utility are given, related to the content of the sources and/or their provenance. Sources are used to support reasoning; contextual knowledge is used.'],
  [1, 2, 'A simple judgement on utility; basic analysis of the content and/or provenance.'],
], ind);
const ED_FOLLOW = (ind: string) => ['Selects a detail from the source that could form the basis of a follow-up enquiry (1)', 'Asks a question linked to that detail (1)', 'Identifies an appropriate type of source (1)', 'Explains how the source might help answer the question (1)', `Example: ${ind}`];
const ED_COMPARE = (ind: string) => lv([[3, 4, 'Explains one valid similarity/difference, supported by specific information about BOTH periods.'], [1, 2, 'A simple comparison with generalised information.']], ind);
const ED_CONSEQ = (ind: string) => [
  'First consequence – Level 2 (3-4 marks): a consequence explained, showing how it followed from the event, supported by specific, accurate information.',
  'First consequence – Level 1 (1-2 marks): a simple or generalised consequence with limited support.',
  'Second consequence – Level 2 (3-4 marks): a second, different consequence explained and supported.',
  'Second consequence – Level 1 (1-2 marks): a simple or generalised second consequence.',
  `Indicative content: ${ind}`,
];
const ED_NARR = (ind: string) => lv([
  [6, 8, 'An analytical narrative that organises the events in a logical sequence and explains how one led to another (causation/consequence). Accurate and relevant information shows wide-ranging knowledge, including beyond the stimulus.'],
  [3, 5, 'A narrative with some organisation and some linking of events. Accurate and relevant information.'],
  [1, 2, 'A simple narrative of events with limited links.'],
], ind, ['Maximum 5 marks for answers that do not go beyond the stimulus points.']);
const ED_IMPORT = (ind: string) => [
  ...['First choice', 'Second choice'].flatMap((c) => [
    `${c} – Level 3 (6-8 marks): explains the importance of the event by analysing its consequences for the situation named; accurate and wide-ranging information.`,
    `${c} – Level 2 (3-5 marks): some explanation of importance; some accurate information.`,
    `${c} – Level 1 (1-2 marks): simple or generalised comment.`,
  ]),
  `Indicative content: ${ind}`,
];
const ED_DIFF = (ind: string) => lv([[3, 4, 'Explains a key difference between the views, supported by details from both interpretations.'], [1, 2, 'Identifies a difference, e.g. by paraphrasing or quoting, but with limited explanation.']], ind);
const ED_WHYDIFF = (ind: string) => lv([[3, 4, 'Explains a valid reason for the difference - e.g. different weight given to different evidence, a different focus, or a different time/viewpoint of the author - supported by the sources or interpretations.'], [1, 2, 'Gives a simple reason with limited support.']], ind);
const ED_INTERP = (ind: string) => lv([
  [13, 16, 'Answers are analytical, using both interpretations and well-selected contextual knowledge to evaluate the view; the overall judgement on how far the view is convincing is fully justified.'],
  [9, 12, 'Answers provide an explained evaluation using both interpretations and relevant contextual knowledge; a judgement is given with some justification.'],
  [5, 8, 'Answers give a simple evaluation using one or both interpretations and some contextual knowledge; the judgement is weakly supported.'],
  [1, 4, 'Answers show basic understanding of the interpretations; a judgement may be asserted.'],
], ind, SPAG);

// AQA descriptors
const A4 = (good: string, simple: string, ind: string) => lv([[3, 4, good], [1, 2, simple]], ind);
const A8 = (d: [string, string, string, string], ind: string) => lv([[7, 8, d[0]], [5, 6, d[1]], [3, 4, d[2]], [1, 2, d[3]]], ind);
const A12 = (d: [string, string, string, string], ind: string) => lv([[10, 12, d[0]], [7, 9, d[1]], [4, 6, d[2]], [1, 3, d[3]]], ind);
const A16 = (ind: string, spag: boolean) => lv([
  [13, 16, 'Complex explanation of stated factor and other factor(s): a sustained line of reasoning with a substantiated judgement. Extends reasoning with range and depth of accurate, relevant knowledge.'],
  [9, 12, 'Developed explanation of stated factor and other factor(s), supported by a range of accurate knowledge.'],
  [5, 8, 'Simple explanation of one or more factors, supported by some accurate knowledge.'],
  [1, 4, 'Basic explanation of one or more factors; limited knowledge.'],
], ind, spag ? SPAG : []);

const sec = (title: string, intro: string, questions: WrittenQ[], source?: string, extra: Partial<MockSection> = {}): MockSection => ({ title, intro, questions, source, ...extra });

// =============================== EDEXCEL PAPER 1: Medicine + Western Front ===============================
interface EdP1 {
  wf: [string, [string, string][]]; enquiry: string; srcA: string; srcB: string; useInd: string; follow: string; followInd: string;
  cmp: [string, string]; why: [string, string, string, string]; q5: [string, string, string, string]; q6: [string, string, string, string];
  topics: { cmp: string; why: string; q5: string; q6: string };
}
const ED1: EdP1[] = [
  {
    wf: ['Describe **two** features of the trench system on the Western Front.', [['Lines of trenches', 'front-line, support and reserve trenches ran parallel, linked by communication trenches'], ['Zig-zag layout', 'traverses stopped blast and enemy fire travelling along the trench'], ['Protection', 'sandbagged parapets and parados, with dugouts cut into the trench wall'], ['Duckboards', 'wooden boards were laid to keep soldiers out of mud and water'], ['No man\'s land', 'the area between opposing trenches, protected by barbed wire']]],
    enquiry: 'the problems involved in treating wounded soldiers on the Western Front',
    srcA: P('Source A', 'from the diary of a stretcher-bearer in the Royal Army Medical Corps, written during the Battle of the Somme, July 1916.', `It took six of us to carry one man the last half-mile, the mud is so deep. Shells kept falling on the communication trench and twice we had to lie flat with our patient on top of the stretcher. By the time we reached the Regimental Aid Post the queue of wounded went out of the door and along the trench. The doctor there has not slept for two days. He can only bandage, give morphia and send them on. We went back for more and found three of the men we had left waiting had died.`),
    srcB: P('Source B', 'from a training booklet for new medical officers issued by the British Army in 1917.', `The wounded man passes along a chain. Stretcher-bearers carry him to the Regimental Aid Post, close to the front line, for first aid. He is then taken to an Advanced Dressing Station, and by motor ambulance to a Casualty Clearing Station, several miles behind the lines, where urgent operations are carried out. From there he goes by train or barge to a Base Hospital on the coast. Officers must ensure that this chain is never broken, for every hour of delay increases the danger of infection.`),
    useInd: 'Source A is useful for the physical difficulties - mud, shelling, the numbers of wounded and exhausted staff - as it is an eyewitness account written at the time by someone carrying the wounded; but it covers one moment of one battle (the Somme, which had exceptionally high casualties: about 57,000 on 1 July). Source B is useful for the official system - RAP, ADS, CCS, base hospitals - and shows the army knew delay caused infection (gas gangrene); but it is an official training document showing how the system should work, not whether it did. Own knowledge: distance from the front, the scale of casualties, shortages of stretcher-bearers, horse-drawn and motor ambulances, the role of FANY and the RAMC.',
    follow: 'Source A', followInd: 'Detail: "the queue of wounded went out of the door". Question: how many casualties did a Regimental Aid Post treat in a day during the Somme? Type of source: RAMC war diaries for a field ambulance unit. How it helps: they record daily numbers of casualties treated and moved on.',
    cmp: ['Explain **one** way in which ideas about the causes of disease in the fourteenth century were similar to ideas in the seventeenth century.', 'Both the Black Death (1348-49) and the Great Plague (1665) were blamed on God\'s punishment for sin and on miasma (bad air); in 1665 people still carried posies and lit fires to clear the air, as in 1348, because germ theory had not been discovered.'],
    why: ['Explain why there were improvements in public health in the nineteenth century.', 'the "Great Stink" (1858)', 'the 1875 Public Health Act', 'Chadwick\'s 1842 report linking poor living conditions to disease; cholera epidemics (1832, 1848, 1854, 1866); John Snow\'s Broad Street pump investigation (1854); Bazalgette\'s London sewers (from 1859); Pasteur\'s germ theory (1861) proving the link between dirt and disease; working-class men gaining the vote (1867) so politicians had to respond; the end of laissez-faire attitudes; the 1875 Act made councils provide clean water, drainage and medical officers.'],
    q5: ['\'Edward Jenner\'s work was the main reason for progress in preventing disease in the period c1700-c1900.\' How far do you agree?', 'smallpox vaccination', 'the germ theory', 'For: Jenner\'s smallpox vaccination (1796) was the first scientific method of prevention; the government made vaccination compulsory in 1853 (enforced from 1871). Against: Jenner did not know why vaccination worked; resistance from the Anti-Vaccination League and inoculators; Pasteur\'s germ theory (1861) and his later vaccines (chicken cholera, anthrax, rabies) and Koch\'s identification of microbes explained disease; public health reforms (1848, 1875 Acts) and Snow\'s work on cholera prevented far more deaths; judgement based on criteria such as scale of impact and long-term significance.'],
    q6: ['\'There was little change in the care of the sick in the period c1250-c1500.\' How far do you agree?', 'hospitals run by the Church', 'remedies made by women at home', 'For: care was based on religion (prayer, rest, the Church\'s hospitals such as St Leonard\'s, York) and the Four Humours (bleeding, purging) throughout; most people were treated at home by women using herbal remedies; physicians trained in Galen\'s ideas; barber-surgeons for simple surgery. Against: growth in the number of hospitals (over 1,000 by 1500); some hospitals cared for the sick poor; the Black Death led to new public health actions; more trained physicians from universities; judgement.'],
    topics: { cmp: 'ed-med-medieval', why: 'ed-med-c18-19', q5: 'ed-med-c18-19', q6: 'ed-med-medieval' },
  },
  {
    wf: ['Describe **two** features of the Battle of the Somme (1916).', [['Aim', 'to relieve pressure on the French army at Verdun and break through German lines'], ['Bombardment', 'a week-long artillery bombardment failed to cut much of the barbed wire'], ['Casualties', 'about 57,000 British casualties on 1 July 1916, the first day'], ['New weapons', 'tanks were used for the first time in September 1916'], ['Length', 'the battle lasted from July to November 1916 for small gains of land']]],
    enquiry: 'how new technology helped doctors to treat wounded soldiers on the Western Front',
    srcA: P('Source A', 'from a letter written by a radiographer at a base hospital in France, 1916.', `The mobile X-ray unit has changed everything here. Before, the surgeon had to probe for the bullet with his fingers or with forceps, and often made the wound worse. Now we can show him exactly where the shrapnel lies, sometimes in places he would never have thought to look. The machines are temperamental. They overheat after an hour, and we must stop, and the queue of men waiting does not stop. But I believe we save limbs every day.`),
    srcB: P('Source B', 'from a report written by an army surgeon for the War Office in 1918.', `Before the Thomas splint was widely used, most men with a fracture of the thigh bone died, from bleeding, shock or infection, during the long journey from the front. Since the splint has been issued to stretcher-bearers, and applied before the man is moved, the death rate for these injuries has fallen dramatically. I recommend that every Regimental Aid Post continues to hold a supply.`),
    useInd: 'Source A: useful for the impact and limits of mobile X-ray units (locating bullets and shrapnel; overheating; long queues); an eyewitness specialist, written at the time; may be enthusiastic about her own work. Source B: useful for the Thomas splint\'s effect on compound fractures of the femur; an expert report written to inform the War Office, so likely based on evidence, though written to persuade (a recommendation). Own knowledge: the Thomas splint (from 1915) cut the death rate for femur fractures from about 80% to about 20%; six mobile X-ray units; blood transfusions and the first blood bank at Cambrai (1917); the Brodie helmet (1915-16); limits - X-rays could not easily be used near the front.',
    follow: 'Source B', followInd: 'Detail: "the death rate for these injuries has fallen dramatically". Question: how many soldiers with femur fractures survived before and after 1915? Type of source: hospital admission records or RAMC statistics. How it helps: gives numbers to compare death rates before and after the splint was introduced.',
    cmp: ['Explain **one** way in which approaches to preventing disease in the period c1250-c1500 were similar to approaches in the period c1500-c1700.', 'In both 1348-49 and 1665 people tried to prevent plague with prayer and religious acts, and with measures to remove "bad air" (cleaning streets, lighting fires, carrying herbs); in both periods local authorities used quarantine and restrictions on movement (e.g. 1665 plague orders shutting up infected houses), because the cause was still not understood.'],
    why: ['Explain why there was rapid progress in the treatment of illness in the twentieth century.', 'penicillin', 'the NHS (1948)', 'Magic bullets: Salvarsan 606 (1909) and Prontosil (1932); Fleming discovered penicillin in 1928, Florey and Chain developed it (1940-41); US government funding and mass production during the Second World War; the NHS (1948) made treatment free at the point of use; science and technology - improved diagnosis (blood tests, scans), DNA (1953) leading to genetic medicine; pharmaceutical companies and government funding of research.'],
    q5: ['\'Science and technology were the main reason for progress in medicine in the period c1700-c1900.\' How far do you agree?', 'microscopes', 'Edward Jenner', 'For: improved microscopes allowed Pasteur and Koch to identify microbes; Koch\'s dyes and methods; chloroform (1847) and carbolic spray (1867); technology for sewers. Against: individuals - Jenner, Pasteur, Koch, Lister, Simpson, Nightingale; government action (1875 Public Health Act); attitudes - resistance to new ideas slowed change; war (the Crimean War and Nightingale); judgement using criteria.'],
    q6: ['\'The Renaissance period (c1500-c1700) was a time of great progress in medicine.\' How far do you agree?', 'Vesalius', 'the Great Plague (1665)', 'Progress: Vesalius\'s *Fabric of the Human Body* (1543) corrected Galen; Harvey\'s discovery of blood circulation (1628); the printing press spread ideas; the Royal Society (1660); Sydenham\'s observation. Limits: treatment hardly changed (bleeding, purging); the Great Plague (1665) was treated with the same methods as 1348; miasma and religious explanations remained; Harvey\'s work had little practical use until blood transfusions in the 20th century; judgement.'],
    topics: { cmp: 'ed-med-renaissance', why: 'ed-med-modern', q5: 'ed-med-c18-19', q6: 'ed-med-renaissance' },
  },
  {
    wf: ['Describe **two** features of the use of gas as a weapon on the Western Front.', [['Chlorine', 'first used by the Germans at Ypres in April 1915; caused choking and lung damage'], ['Phosgene', 'more deadly than chlorine and harder to detect; symptoms could be delayed'], ['Mustard gas', 'used from 1917; caused blisters, blindness and internal damage'], ['Protection', 'gas helmets and later box respirators were issued to soldiers'], ['Effect', 'gas caused fear and many casualties, though a relatively small share of deaths']]],
    enquiry: 'the conditions in the trenches that affected the health of soldiers',
    srcA: P('Source A', 'from a letter written by a British officer to his family, December 1914.', `We have been standing in water up to our knees for four days. It is impossible to keep dry and there is no chance to change. Several men in my platoon can hardly walk - their feet are swollen and numb and turn a dreadful colour. The rats are bold enough to run over us as we sleep, and the lice are worse than the Germans. Yet the men are cheerful. They make tea in their helmets and sing.`),
    srcB: P('Source B', 'from an order given to all battalions by a British Army commander, 1915.', `Trench foot is preventable. Each man must carry a dry pair of socks and change them daily. Feet are to be rubbed with whale oil before entering the trenches. Officers will inspect men's feet regularly and will be held responsible for cases of trench foot in their units.`),
    useInd: 'Source A: useful for waterlogged trenches, trench foot, rats and lice from an eyewitness at the time; a private letter, so possibly honest, though he may play down suffering to avoid worrying his family ("the men are cheerful"); it is from the first winter of the war. Source B: useful for showing the army\'s understanding of trench foot and how it was prevented (dry socks, whale oil, inspections); official order - shows intentions, not whether they worked. Own knowledge: trench foot could lead to gangrene and amputation; about 20,000 cases in the British army in winter 1914-15; trench fever spread by lice; shell shock; cold and exposure; duckboards were introduced.',
    follow: 'Source A', followInd: 'Detail: "their feet are swollen and numb". Question: how common was trench foot in the British army in 1914-15 and did cases fall after new orders? Type of source: army medical statistics or battalion war diaries. How it helps: shows the number of cases over time.',
    cmp: ['Explain **one** way in which government action on public health in the nineteenth century was different from government action in the twentieth century.', 'In the nineteenth century the government was slow to act (laissez-faire): the 1848 Public Health Act was voluntary, and only the 1875 Act made councils act on water and sewers. In the twentieth century the government took direct responsibility - the Liberal reforms, the NHS (1948), the Clean Air Acts (1956, 1968) and national campaigns against smoking and for vaccination.'],
    why: ['Explain why there was little progress in the treatment of disease in the period c1250-c1500.', 'the Church', 'the theory of the Four Humours', 'The Church controlled education and taught Galen\'s ideas as correct, discouraging challenges; dissection was limited; the Four Humours led to bleeding and purging; belief that disease was a punishment from God; no knowledge of germs; astrology; physicians trained by reading books rather than observation; lack of government organisation; the Black Death showed treatments did not work.'],
    q5: ['\'Alexander Fleming deserves the most credit for the development of penicillin.\' How far do you agree?', 'Florey and Chain', 'the Second World War', 'Fleming noticed the mould killing bacteria (1928) and published his findings, but did not develop it; Florey and Chain purified penicillin and tested it on mice and a human patient (1940-41); the Second World War created demand and US government funding allowed mass production by drug companies; by D-Day (1944) there was enough to treat Allied wounded; chance and technology; judgement.'],
    q6: ['\'Pasteur\'s germ theory was the most important turning point in medicine in the period c1700-c1900.\' How far do you agree?', 'Robert Koch', 'Joseph Lister', 'For: germ theory (1861) explained disease, led to Koch identifying specific bacteria (anthrax 1876, TB 1882, cholera 1883), vaccines, Lister\'s antiseptic surgery (1867), and public health reform. Against: Jenner\'s vaccination (1796) came first; anaesthetics (Simpson\'s chloroform, 1847); the 1875 Public Health Act had more direct impact on deaths; germ theory took time to be accepted and had little effect on treatment until the 20th century; judgement.'],
    topics: { cmp: 'ed-med-modern', why: 'ed-med-medieval', q5: 'ed-med-modern', q6: 'ed-med-c18-19' },
  },
];
function edP1(t: number): MockTest {
  const d = ED1[t];
  const q4 = examQ(`${d.why[0]}\n\nYou may use the following in your answer:\n- ${d.why[1]}\n- ${d.why[2]}\n\nYou **must** also use information of your own.`, 12, ED_WHY(d.why[3]), { meta: 'Question 4 · AO1, AO2', time: 18 });
  const essay = (x: [string, string, string, string], n: string) => examQ(`${x[0]} Explain your answer.\n\nYou may use the following in your answer:\n- ${x[1]}\n- ${x[2]}\n\nYou **must** also use information of your own.`, 20, ED_HOWFAR(x[3]), { meta: `Question ${n} · AO1, AO2 (16 marks) + SPaG (4 marks)`, time: 25 });
  return {
    id: `history-ed-p1-t${t + 1}`, paperId: 'history-ed-p1', n: (t + 1) as 1 | 2 | 3, title: `Practice paper ${t + 1}`,
    focus: ['Trenches, treating the wounded, public health and vaccination.', 'The Somme, new medical technology, 20th-century treatment and the Renaissance.', 'Gas, trench conditions, government action and the germ theory.'][t],
    sections: [
      sec('Section A: The British sector of the Western Front, 1914-18', 'Answer Questions 1 and 2. You should spend about 30 minutes on this section.', [
        w('1', examQ(d.wf[0], 4, features(d.wf[1]), { meta: 'Question 1 · AO1', time: 5 }), 'ed-med-wf', 8),
        w('2(a)', examQ(`Study Sources A and B.\n\nHow useful are Sources A and B for an enquiry into ${d.enquiry}?\n\nExplain your answer, using Sources A and B and your knowledge of the historical context.`, 8, ED_USE(d.useInd), { meta: 'Question 2(a) · AO3', time: 12 }), 'ed-med-wf'),
        w('2(b)', examQ(`Study ${d.follow}.\n\nHow could you follow up ${d.follow} to find out more about ${d.enquiry}?\n\nIn your answer, you must give the question you would ask and the type of source you could use. Set it out as:\n- Detail in ${d.follow} that I would follow up:\n- Question I would ask:\n- What type of source I could use:\n- How this might help answer my question:`, 4, ED_FOLLOW(d.followInd), { meta: 'Question 2(b) · AO3', time: 6 }), 'ed-med-wf', 8),
      ], `${d.srcA}\n\n${d.srcB}`),
      sec('Section B: Medicine in Britain, c1250-present', 'Answer Questions 3 and 4. Then answer EITHER Question 5 OR Question 6. You should spend about 45 minutes on this section.', [
        w('3', examQ(d.cmp[0], 4, ED_COMPARE(d.cmp[1]), { meta: 'Question 3 · AO1, AO2', time: 6 }), d.topics.cmp, 8),
        w('4', q4, d.topics.why, 20),
      ]),
      sec('Section B (continued): answer EITHER Question 5 OR Question 6', 'Spelling, punctuation, grammar and the use of specialist terminology are assessed in this question (4 marks).', [
        w('5', essay(d.q5, '5'), d.topics.q5, 28), w('6', essay(d.q6, '6'), d.topics.q6, 28),
      ], undefined, { chooseOne: true }),
    ],
  };
}

// =============================== EDEXCEL PAPER 2: Cold War + Early Elizabethan England ===============================
interface EdP2 {
  conseq: [string, string]; narr: [string, string, string, string]; imp: [string[], string];
  feat: [string, [string, string][]]; why: [string, string, string, string]; c1: [string, string, string, string]; c2: [string, string, string, string];
  topics: { conseq: string; narr: string; imp: string; feat: string; why: string; c1: string; c2: string };
}
const ED2: EdP2[] = [
  {
    conseq: ['Explain **two** consequences of the Berlin Blockade (1948-49).', 'Germany was formally divided: the Federal Republic of Germany (West) and the German Democratic Republic (East) were set up in 1949; NATO was formed in April 1949, committing the USA to defend Western Europe; the West gained a propaganda victory - the airlift showed the USA would protect West Berlin; mistrust deepened and the Cold War hardened into two armed blocs (leading to the Warsaw Pact in 1955).'],
    narr: ['Write a narrative account analysing the key events of the Cuban Missile Crisis in 1962.', 'the U-2 spy plane photographs (October 1962)', 'the naval blockade (quarantine) of Cuba', 'Context: Castro\'s revolution (1959) and the Bay of Pigs (1961); Khrushchev agreed to place nuclear missiles in Cuba; U-2 photographs (14 October) revealed missile sites; Kennedy formed ExComm and rejected an air strike; the quarantine announced on 22 October; Soviet ships turned back on 24 October; a U-2 was shot down over Cuba on 27 October; Khrushchev\'s two letters; the agreement on 28 October - missiles withdrawn in return for a US promise not to invade Cuba and a secret promise to remove Jupiter missiles from Turkey; consequences: the hotline (1963) and Limited Test Ban Treaty (1963).'],
    imp: [['the importance of the Truman Doctrine (1947) for the development of the Cold War', 'the importance of the Hungarian Uprising (1956) for relations between the USSR and the West', 'the importance of the Soviet invasion of Afghanistan (1979) for the end of détente'], 'Truman Doctrine: a public commitment to "contain" communism, ending US isolationism; led to Marshall Aid and divided Europe economically; Stalin saw it as aggressive (Cominform 1947). Hungary: Soviet tanks crushed the uprising, showing the USSR would use force to keep control and the West would not intervene - confirming spheres of influence and damaging hopes after Stalin\'s death. Afghanistan: the Carter Doctrine, the US boycott of the 1980 Moscow Olympics, SALT II not ratified, US support for the mujahideen - the start of the "Second Cold War".'],
    feat: ['Describe **two** features of the Elizabethan Religious Settlement (1559).', [['Act of Supremacy', 'Elizabeth became Supreme Governor of the Church of England; clergy and officials had to swear an oath'], ['Act of Uniformity', 'set the 1559 Book of Common Prayer and the appearance of churches; required attendance at church'], ['Fines', 'those who did not attend church (recusants) could be fined 12d per week'], ['Royal Injunctions', 'instructions to clergy, e.g. teaching the supremacy and a Bible in English in every church'], ['A "middle way"', 'Protestant doctrine with some Catholic features such as vestments and ornaments']]],
    why: ['Explain why Mary, Queen of Scots, was a threat to Elizabeth I in the years 1568-87.', 'the Babington Plot (1586)', 'Catholic support', 'Mary had a strong claim to the English throne as Henry VII\'s great-granddaughter and was seen by many Catholics as the rightful queen; she arrived in England in 1568; the Revolt of the Northern Earls (1569); the Papal Bull (1570) excommunicating Elizabeth; the Ridolfi (1571) and Throckmorton (1583) plots aimed to put her on the throne with foreign help; Spanish and French support; the Babington Plot (1586) - her letters were intercepted by Walsingham, leading to her trial and execution in 1587.'],
    c1: ['\'The main reason for the failure of the Revolt of the Northern Earls (1569) was poor planning.\' How far do you agree?', 'the earls\' changing plans', 'the Earl of Sussex\'s army', 'Poor planning: the plan to marry Mary to the Duke of Norfolk collapsed when Norfolk submitted; the earls rose in haste and Mary was moved to Coventry, out of reach; Spanish troops never arrived. Other factors: Elizabeth\'s quick response - Sussex and a large royal army marched north; limited support beyond the north; the earls retreated and fled to Scotland; about 450 rebels were executed; judgement.'],
    c2: ['\'The main reason for English voyages of exploration in the years 1558-88 was the search for wealth.\' How far do you agree?', 'Drake\'s circumnavigation (1577-80)', 'the attempted colony at Virginia (1585)', 'Wealth: privateering and raids on Spanish treasure ships; Drake returned with treasure worth a vast sum; new trade routes and trading companies. Other reasons: rivalry with Spain and national prestige; religion; adventure and personal fame; improved technology (galleons, navigational instruments); the attempt to found a colony at Roanoke (1585) aimed at land, raw materials and a base against Spain; judgement.'],
    topics: { conseq: 'ed-cw-origins', narr: 'ed-cw-crises', imp: 'ed-cw-crises', feat: 'ed-eliz-gov', why: 'ed-eliz-spain', c1: 'ed-eliz-spain', c2: 'ed-eliz-society' },
  },
  {
    conseq: ['Explain **two** consequences of the building of the Berlin Wall (1961).', 'It stopped the flow of skilled East Germans to the West, stabilising the GDR economy; it became a symbol of the division of Europe and of communist repression - Kennedy\'s "Ich bin ein Berliner" speech (1963); it reduced the immediate crisis over Berlin - Kennedy said "a wall is a hell of a lot better than a war"; families were divided and people were killed trying to cross; it increased tension, e.g. the stand-off at Checkpoint Charlie (October 1961).'],
    narr: ['Write a narrative account analysing the key events of the Hungarian Uprising in 1956.', 'Nagy becoming leader', 'Soviet tanks entering Budapest', 'Context: Khrushchev\'s "secret speech" and de-Stalinisation raised hopes; protests in Budapest in October 1956; Rákosi had been removed and Nagy became prime minister; Soviet troops withdrew briefly; Nagy announced plans to leave the Warsaw Pact and hold free elections; on 4 November Soviet tanks entered Budapest; thousands were killed and many fled; Kádár installed; Nagy executed in 1958; the West condemned the invasion but did not intervene (Suez crisis distracted Britain and France).'],
    imp: [['the importance of the Yalta and Potsdam conferences (1945) for relations between the superpowers', 'the importance of the Prague Spring (1968) for Soviet control of Eastern Europe', 'the importance of Gorbachev\'s "new thinking" for the end of the Cold War'], 'Yalta/Potsdam: agreements on dividing Germany and free elections; at Potsdam Truman\'s tougher approach, news of the atomic bomb and disputes over Poland and reparations increased mistrust. Prague Spring: Dubček\'s reforms crushed by Warsaw Pact troops; the Brezhnev Doctrine claimed the right to intervene, tightening control. Gorbachev: glasnost and perestroika, cuts in military spending, the INF Treaty (1987), the Sinatra Doctrine allowing Eastern Europe to choose its own path - leading to 1989 revolutions.'],
    feat: ['Describe **two** features of the Elizabethan theatre.', [['Purpose-built theatres', 'e.g. The Theatre (1576) and the Rose, built outside the City of London'], ['Audiences', 'all classes attended; the poorest stood as "groundlings" for a penny'], ['Acting companies', 'companies needed a noble patron, e.g. the Lord Chamberlain\'s Men'], ['Opposition', 'Puritans and City authorities said theatres spread disorder and disease'], ['Performances', 'held in the afternoon, using daylight, with men and boys playing female roles']]],
    why: ['Explain why there was conflict between England and Spain in the years 1569-88.', 'the Netherlands', 'Drake\'s raids', 'Religious differences - Philip II was a Catholic champion; English support for the Dutch Protestant rebels; the Treaty of Nonsuch (1585) sent Leicester and an English army to the Netherlands; privateering and Drake\'s raids on Spanish treasure ships and colonies; Spanish involvement in plots (Ridolfi, Throckmorton); trade rivalry in the New World; the execution of Mary, Queen of Scots (1587); Drake\'s raid on Cádiz (1587).'],
    c1: ['\'The main problem Elizabeth faced when she became queen in 1558 was her financial weakness.\' How far do you agree?', 'the Crown\'s debts', 'Elizabeth\'s gender', 'Finance: the Crown was about £300,000 in debt and income was limited; wars had been costly. Other problems: legitimacy (Catholics saw her as illegitimate); gender and the expectation she would marry; religious division; foreign threats from France and Spain; the claim of Mary, Queen of Scots, and the "Auld Alliance"; judgement.'],
    c2: ['\'The main reason for the increase in poverty in Elizabethan England was population growth.\' How far do you agree?', 'rising prices', 'changes in farming', 'Population growth (from about 3 million to about 4 million) pushed up prices and lowered wages; inflation; enclosure and sheep farming reduced jobs; bad harvests (e.g. the 1590s); the decline of the cloth trade; the dissolution of the monasteries removed charity; judgement.'],
    topics: { conseq: 'ed-cw-crises', narr: 'ed-cw-crises', imp: 'ed-cw-end', feat: 'ed-eliz-society', why: 'ed-eliz-spain', c1: 'ed-eliz-gov', c2: 'ed-eliz-society' },
  },
  {
    conseq: ['Explain **two** consequences of the Soviet invasion of Afghanistan (1979).', 'The end of détente: the Carter Doctrine (1980) and the US Senate did not ratify SALT II; the USA and many allies boycotted the 1980 Moscow Olympics (and the USSR boycotted Los Angeles in 1984); the USA supplied the mujahideen with weapons; a costly war drained the Soviet economy and damaged morale, contributing to the USSR\'s collapse; Reagan\'s "Second Cold War" and increased arms spending.'],
    narr: ['Write a narrative account analysing the key events of 1989-91 that led to the collapse of the Soviet Union.', 'the fall of the Berlin Wall (November 1989)', 'the attempted coup (August 1991)', 'Gorbachev\'s reforms and the Sinatra Doctrine; Poland\'s free elections (1989); Hungary opened its border with Austria; the fall of the Berlin Wall (9 November 1989); revolutions across Eastern Europe; German reunification (1990); the Warsaw Pact dissolved (1991); the Baltic states demanded independence; hard-liners\' coup in August 1991 failed, strengthening Yeltsin; Gorbachev resigned on 25 December 1991 and the USSR ceased to exist.'],
    imp: [['the importance of the Marshall Plan (1947) for the development of the Cold War', 'the importance of the formation of the Warsaw Pact (1955) for relations between East and West', 'the importance of the INF Treaty (1987) for the end of the Cold War'], 'Marshall Plan: $13 billion of aid tied Western Europe to the USA economically; Stalin rejected it for the Eastern bloc and set up Comecon - "dollar imperialism"; Europe divided. Warsaw Pact: a military alliance in response to West Germany joining NATO; two armed blocs; used to justify intervention (Hungary, Czechoslovakia). INF Treaty: first treaty to remove a whole class of nuclear weapons; built trust between Reagan and Gorbachev; led to further arms reductions.'],
    feat: ['Describe **two** features of the Spanish Armada\'s campaign in 1588.', [['Plan', 'the fleet was to join the Duke of Parma\'s army in the Netherlands and invade England'], ['Crescent formation', 'the fleet sailed up the Channel in a defensive crescent that was hard to break'], ['Fireships', 'English fireships at Calais forced the Spanish to cut their anchors and scatter'], ['Gravelines', 'the English attacked at close range with superior guns'], ['Storms', 'returning around Scotland and Ireland, many ships were wrecked']]],
    why: ['Explain why the Puritans were a challenge to Elizabeth\'s religious settlement in the years 1558-69.', 'the crucifix controversy', 'the vestment controversy (1566)', 'Puritans wanted to remove Catholic features from the Church; some bishops (e.g. Grindal) had Puritan sympathies and had been in exile under Mary; Elizabeth kept a crucifix in the royal chapel; the 1566 vestments controversy - Archbishop Parker\'s Advertisements required vestments and 37 London clergy were suspended; Puritan MPs in Parliament; Puritans were influential at court; they threatened the "middle way" and Elizabeth\'s authority as Supreme Governor.'],
    c1: ['\'The main reason why Mary, Queen of Scots, was executed in 1587 was the Babington Plot.\' How far do you agree?', 'Walsingham\'s spy network', 'the Bond of Association (1584)', 'Babington Plot: Mary\'s letters approving the plot gave evidence of treason. Other reasons: Walsingham deliberately trapped her through a double agent and coded letters in beer barrels; the Bond of Association and the Act for the Queen\'s Safety (1585) made execution lawful; earlier plots; pressure from Parliament and the Privy Council; the threat from Spain; Elizabeth\'s reluctance; judgement.'],
    c2: ['\'Improvements in technology were the main reason for the growth of English exploration in the years 1558-88.\' How far do you agree?', 'navigational instruments', 'the design of ships', 'Technology: the astrolabe, quadrant and improved maps; the galleon - faster, more manoeuvrable, could carry more guns and supplies. Other reasons: the search for wealth and trade; rivalry with Spain and privateering; individuals such as Drake, Raleigh and Hawkins; the support of Elizabeth and investors; the printing of travel accounts; judgement.'],
    topics: { conseq: 'ed-cw-end', narr: 'ed-cw-end', imp: 'ed-cw-origins', feat: 'ed-eliz-spain', why: 'ed-eliz-gov', c1: 'ed-eliz-spain', c2: 'ed-eliz-society' },
  },
];
function edP2(t: number): MockTest {
  const d = ED2[t];
  return {
    id: `history-ed-p2-t${t + 1}`, paperId: 'history-ed-p2', n: (t + 1) as 1 | 2 | 3, title: `Practice paper ${t + 1}`,
    focus: ['Berlin Blockade, Cuba and containment · the Religious Settlement and Mary, Queen of Scots.', 'Berlin Wall, Hungary and Gorbachev · theatre, Spain and poverty.', 'Afghanistan, 1989-91 and the Marshall Plan · the Armada, Puritans and exploration.'][t],
    sections: [
      sec('Section A: Period study – Superpower relations and the Cold War, 1941-91', 'Answer Questions 1, 2 and 3. You should spend about 50 minutes on this section.', [
        w('1', examQ(d.conseq[0], 8, ED_CONSEQ(d.conseq[1]), { meta: 'Question 1 · AO1, AO2', time: 10 }), d.topics.conseq),
        w('2', examQ(`${d.narr[0]}\n\nYou may use the following in your answer:\n- ${d.narr[1]}\n- ${d.narr[2]}\n\nYou **must** also use information of your own.`, 8, ED_NARR(d.narr[3]), { meta: 'Question 2 · AO1, AO2', time: 12 }), d.topics.narr),
        w('3', examQ(`Explain **two** of the following:\n${d.imp[0].map((x) => `- ${x[0].toUpperCase()}${x.slice(1)}.`).join('\n')}`, 16, ED_IMPORT(d.imp[1]), { meta: 'Question 3 · AO1, AO2 (8 marks for each of your two choices)', time: 25 }), d.topics.imp, 24),
      ]),
      sec('Section B: British depth study – Early Elizabethan England, 1558-88', 'Answer Questions 4(a) and 4(b). You should spend about 25 minutes on these questions.', [
        w('4(a)', examQ(d.feat[0], 4, features(d.feat[1]), { meta: 'Question 4(a) · AO1', time: 5 }), d.topics.feat, 8),
        w('4(b)', examQ(`${d.why[0]}\n\nYou may use the following in your answer:\n- ${d.why[1]}\n- ${d.why[2]}\n\nYou **must** also use information of your own.`, 12, ED_WHY(d.why[3]), { meta: 'Question 4(b) · AO1, AO2', time: 18 }), d.topics.why, 20),
      ]),
      sec('Section B (continued): answer EITHER 4(c)(i) OR 4(c)(ii)', 'You should spend about 25 minutes on this question.', [
        w('4(c)(i)', examQ(`${d.c1[0]} Explain your answer.\n\nYou may use the following in your answer:\n- ${d.c1[1]}\n- ${d.c1[2]}\n\nYou **must** also use information of your own.`, 16, ED_HOWFAR(d.c1[3], false), { meta: 'Question 4(c)(i) · AO1, AO2', time: 25 }), d.topics.c1, 26),
        w('4(c)(ii)', examQ(`${d.c2[0]} Explain your answer.\n\nYou may use the following in your answer:\n- ${d.c2[1]}\n- ${d.c2[2]}\n\nYou **must** also use information of your own.`, 16, ED_HOWFAR(d.c2[3], false), { meta: 'Question 4(c)(ii) · AO1, AO2', time: 25 }), d.topics.c2, 26),
      ], undefined, { chooseOne: true }),
    ],
  };
}

// =============================== EDEXCEL PAPER 3: Weimar and Nazi Germany ===============================
interface EdP3 { srcA: string; infer: [string, string]; why: [string, string, string, string]; enquiry: string; srcB: string; srcC: string; useInd: string; i1: string; i2: string; view: string; diffInd: string; whyInd: string; agreeInd: string; topics: { infer: string; why: string; s: string } }
const ED3: EdP3[] = [
  {
    srcA: P('Source A', 'from the memories of a German woman, recorded in 1962, describing life in Berlin in 1923.', `My husband was paid twice a day, and I would meet him at the factory gate at noon so I could run to the shops before the prices went up again. Once I queued for an hour for bread and when I reached the counter the price had doubled. My mother had saved all her life; her savings bought a single stamp. People blamed the government, the French, the Jews, anybody. Nobody believed in the Republic after that.`),
    infer: ['Give **two** things you can infer from Source A about the effects of hyperinflation in 1923.', 'prices rose so fast that wages had to be spent immediately; ordinary families struggled to buy food; people with savings (often the middle classes) lost almost everything; people lost faith in the Weimar Republic and looked for scapegoats.'],
    why: ['Explain why the Weimar Republic faced opposition in the years 1919-23.', 'the Treaty of Versailles', 'the Kapp Putsch (1920)', 'The "stab in the back" myth and the "November criminals"; the Treaty of Versailles (diktat, loss of land, war guilt, reparations, army limited to 100,000); weaknesses of the constitution (proportional representation, Article 48); the Spartacist uprising (1919); the Kapp Putsch (1920) and the army\'s refusal to act; political murders (Erzberger 1921, Rathenau 1922); the occupation of the Ruhr and hyperinflation (1923); the Munich Putsch (1923).'],
    enquiry: 'the attitudes of young people towards the Hitler Youth',
    srcB: P('Source B', 'from a speech by the leader of the Hitler Youth to a rally of members in 1936.', `You are the guarantee of Germany's future. Here there are no rich and poor, no sons of workers and sons of bosses - only comrades. You march together, you camp together, you sing together. The boy who serves in the Hitler Youth today will be the soldier who defends the Fatherland tomorrow.`),
    srcC: P('Source C', 'from a report sent abroad secretly in 1938 by members of the banned Social Democratic Party (SPD), based on reports from inside Germany.', `Many young people are tired of the endless marching and drill. Attendance at meetings has fallen in several towns, even though membership is now almost compulsory. In some cities groups of youths gather to listen to American music and avoid the patrols. Parents complain that their children are never at home.`),
    useInd: 'Source B: useful for the Nazis\' aims and the image the regime wanted to give (comradeship, equality, preparing for war); but it is propaganda from the movement\'s leader, so it does not show what young people actually felt. Source C: useful for evidence of boredom, falling attendance and youth groups that rejected the Hitler Youth (e.g. the Swing Youth, Edelweiss Pirates); written by opponents of the Nazis, so it may exaggerate discontent, but it was a secret report based on reports from inside Germany. Context: membership became compulsory in 1936 (Hitler Youth Law) and more strictly in 1939; activities - camping, sport, military training; League of German Maidens for girls.',
    i1: `**Interpretation 1** – from a history of Nazi Germany written in 2005 (practice interpretation written for this app).\n\n> For millions of German teenagers the Hitler Youth was exciting. It offered adventure, uniforms, camping, sport and a sense of belonging that the Weimar years had never given them. Many joined willingly long before membership became compulsory, and many remembered those years with fondness.`,
    i2: `**Interpretation 2** – from a book about young people in the Third Reich written in 2015 (practice interpretation written for this app).\n\n> As the Hitler Youth became compulsory and more military, the enthusiasm of the early years faded. Drill replaced adventure. A minority, such as the Edelweiss Pirates, openly rejected it, and many more simply went along with it because they had no choice.`,
    view: 'how far young people supported the Hitler Youth',
    diffInd: 'Interpretation 1 argues that the Hitler Youth was popular and joined willingly ("exciting", "joined willingly"); Interpretation 2 argues that support faded and many only conformed because membership was compulsory ("no choice"), with some open opposition.',
    whyInd: 'They focus on different periods (Interpretation 1 on the early years and the appeal of activities; Interpretation 2 on the later, compulsory, militarised years); they may use different evidence (memories of former members vs reports of opposition such as the Edelweiss Pirates or SPD reports, like Sources B and C).',
    agreeInd: 'Agree: compulsory membership (1936, 1939 laws); military drill and preparing for war; falling attendance; the Edelweiss Pirates and Swing Youth; Source C. Disagree: membership rose to about 7 million by 1939 (most young people); the appeal of activities, sport, trips; many former members remembered it positively; Interpretation 1; Source B shows the attractive image. Judgement: how far the view applies to different periods and groups.',
    topics: { infer: 'ed-ger-weimar', why: 'ed-ger-weimar', s: 'ed-ger-life' },
  },
  {
    srcA: P('Source A', 'from a report in a German newspaper about a Nazi election rally in July 1932.', `Long before Hitler arrived the stadium was full - shopkeepers, students, farmers, women with children on their shoulders. When the aeroplane carrying the Führer appeared in the sky the crowd roared. He spoke of work and bread, of an end to the endless squabbling of the parties, of Germany great again. Unemployed men who had queued for soup that morning stood with tears on their faces.`),
    infer: ['Give **two** things you can infer from Source A about the reasons for support for the Nazis in 1932.', 'the Nazis appealed to many different groups, not just one class; modern propaganda (flying in by aeroplane, mass rallies) created excitement; the Depression and unemployment made promises of "work and bread" attractive; people were frustrated with weak coalition governments; Hitler\'s promises of national greatness appealed to resentment about Versailles.'],
    why: ['Explain why the Nazis were able to increase their support in the years 1929-32.', 'the Depression', 'propaganda', 'The Wall Street Crash (1929) and withdrawal of US loans; unemployment rose to about 6 million by 1932; weak coalition governments and rule by decree (Article 48); fear of communism among the middle classes and businessmen; Goebbels\' propaganda - posters, rallies, radio, Hitler\'s flights across Germany; the SA\'s image of order; Hitler\'s leadership and promises to different groups; funding from businessmen (e.g. Krupp, Thyssen); Nazi seats rose from 12 (1928) to 230 (July 1932).'],
    enquiry: 'the lives of women in Nazi Germany',
    srcB: P('Source B', 'from a leaflet produced by the Nazi Party in 1934.', `A woman's world is her husband, her family, her children and her home. The German mother who raises healthy children for the nation serves the Fatherland as truly as the soldier at the front. The Nazi state honours her with the Cross of Honour of the German Mother.`),
    srcC: P('Source C', 'from the diary of a German woman doctor, written in 1937.', `Today I was told that my post at the hospital will be given to a man. Seventeen years of training and work - and now I am to go home and have babies, at the age of forty-one. My younger sister, who has three children, says the loans and medals make her feel valued for the first time. We no longer speak about politics.`),
    useInd: 'Source B: useful for the Nazi ideal of women (Kinder, Küche, Kirche) and how they encouraged motherhood (Mother\'s Cross); official propaganda - shows aims, not reality. Source C: useful for the effect on professional women (women doctors, teachers and civil servants dismissed from 1933-36) and different experiences (the sister values loans and medals); a private diary written at the time, likely honest but one person\'s view. Context: marriage loans (1933), the Lebensborn programme, the Law for the Encouragement of Marriage, women banned from being judges or lawyers (1936); after 1937 women were needed back in work.',
    i1: `**Interpretation 1** – from a textbook about Nazi Germany written in 2008 (practice interpretation written for this app).\n\n> Nazi policies turned the clock back for German women. They were pushed out of the professions, excluded from politics and valued only as mothers. The regime saw women as servants of the nation's racial future, not as individuals.`,
    i2: `**Interpretation 2** – from a history of women in the Third Reich written in 2018 (practice interpretation written for this app).\n\n> Many German women did not see Nazi policies as a loss. Housewives and mothers in particular felt that their work was respected at last. Marriage loans and benefits made a real difference to family life, and many women welcomed the stability the regime seemed to bring.`,
    view: 'whether Nazi policies were good for German women',
    diffInd: 'Interpretation 1 sees Nazi policies as harmful - women lost rights and opportunities and were valued only as mothers; Interpretation 2 argues many women welcomed the policies and felt respected, benefiting from loans and benefits.',
    whyInd: 'Different focus: Interpretation 1 focuses on professional women and rights; Interpretation 2 focuses on housewives and mothers. They may use different evidence - laws and dismissals vs memories and testimony of ordinary women.',
    agreeInd: 'Agree (Interpretation 2): marriage loans (1933), family allowances, the Mother\'s Cross, the popularity of the regime among many women; Source C\'s sister. Disagree: dismissal of women doctors, lawyers and civil servants; exclusion from the Reichstag; Lebensborn; reduced education for girls; contradictions after 1937 when women were needed in factories; Source C\'s doctor; Interpretation 1. Judgement.',
    topics: { infer: 'ed-ger-rise', why: 'ed-ger-rise', s: 'ed-ger-life' },
  },
  {
    srcA: P('Source A', 'from an account by a Berlin factory worker, written after he escaped from Germany in 1937.', `You learned to say nothing. The block warden knew who visited every flat. A man in our workshop made a joke about Göring's medals; two days later he did not come to work and nobody asked where he was. At the factory meetings we raised our arms and shouted with the rest. At home we spoke in whispers, with the radio turned up.`),
    infer: ['Give **two** things you can infer from Source A about life in the Nazi police state.', 'people were afraid to speak openly; ordinary Germans were watched by informers such as block wardens; people who criticised the regime disappeared (taken by the Gestapo/sent to camps); people conformed in public while privately disagreeing.'],
    why: ['Explain why there was an economic recovery in Germany in the years 1924-29.', 'the Dawes Plan (1924)', 'Gustav Stresemann', 'Stresemann ended passive resistance in the Ruhr and introduced the Rentenmark (1923) to end hyperinflation; the Dawes Plan (1924) reduced annual reparations and gave US loans (800 million gold marks); French troops left the Ruhr (1925); the Young Plan (1929) reduced reparations further; industrial output grew; but recovery depended on American loans.'],
    enquiry: 'the attitudes of German workers towards Nazi economic policies',
    srcB: P('Source B', 'from a poster produced in 1937 by the Strength Through Joy (KdF) organisation.', `Your holiday is on us! A week by the sea, a concert, a cruise to Madeira - Strength Through Joy brings to the worker what was once only for the rich. Save five marks a week and own a People's Car!`),
    srcC: P('Source C', 'from a secret report on conditions in Germany, written in 1938 by members of the banned SPD.', `Workers grumble about long hours and wages that buy less than before. They cannot change jobs without permission and there is no trade union to speak for them. Yet they say: at least there is work. Few want to return to the years of unemployment, and the KdF trips are popular.`),
    useInd: 'Source B: useful for the regime\'s promises to workers (KdF holidays, the Volkswagen scheme) - propaganda designed to win support, so it shows aims; context: few workers ever received a Volkswagen. Source C: useful for workers\' mixed attitudes - grievances about hours, wages and the lack of unions, but gratitude for jobs and KdF; written by opponents, so it may stress discontent, yet it admits the popularity of KdF. Context: the German Labour Front (DAF) replaced trade unions (1933); Beauty of Labour; unemployment fell from about 6 million to about 0.3 million by 1939 (with "invisible unemployment"); working hours rose; real wages barely rose.',
    i1: `**Interpretation 1** – from a history of the Third Reich written in 2003 (practice interpretation written for this app).\n\n> For most German workers the Nazi years brought work, security and pride after the misery of the Depression. Schemes like Strength Through Joy were genuinely popular, and many workers felt the regime cared about them.`,
    i2: `**Interpretation 2** – from a study of German workers written in 2016 (practice interpretation written for this app).\n\n> Workers paid a high price for full employment. They lost their unions, their right to strike and their freedom to change jobs. Hours grew longer while wages stood still. Strength Through Joy was a distraction from the fact that workers had less control over their lives than ever before.`,
    view: 'whether German workers were better off under the Nazis',
    diffInd: 'Interpretation 1 argues workers were better off - work, security and popular schemes; Interpretation 2 argues they were worse off - loss of rights, longer hours and stagnant wages, with KdF a distraction.',
    whyInd: 'Different emphasis: Interpretation 1 compares with the Depression and focuses on jobs and leisure; Interpretation 2 focuses on rights, hours and wages. They may draw on different evidence - workers\' memories and KdF participation vs wage and hours statistics and SPD reports.',
    agreeInd: 'Agree (Interpretation 2): DAF replaced trade unions (May 1933); strikes banned; longer hours (about 60 a week in some industries by 1939); real wages barely above 1928 levels; Volkswagen savers never received cars; Source C\'s grievances. Disagree: unemployment fell dramatically; KdF holidays and Beauty of Labour; stability; Source C\'s "at least there is work"; Interpretation 1. Judgement.',
    topics: { infer: 'ed-ger-control', why: 'ed-ger-weimar', s: 'ed-ger-life' },
  },
];
function edP3(t: number): MockTest {
  const d = ED3[t];
  return {
    id: `history-ed-p3-t${t + 1}`, paperId: 'history-ed-p3', n: (t + 1) as 1 | 2 | 3, title: `Practice paper ${t + 1}`,
    focus: ['Hyperinflation, opposition 1919-23 and young people.', 'The rise of the Nazis 1929-32 and women.', 'The police state, recovery 1924-29 and workers.'][t],
    sections: [
      sec('Section A', 'Answer Questions 1 and 2. You should spend about 20 minutes on this section.', [
        w('1', examQ(`Study Source A.\n\n${d.infer[0]}\n\nComplete the table below for each inference:\n- What I can infer:\n- Details in the source that tell me this:`, 4, inference(d.infer[1]), { meta: 'Question 1 · AO3', time: 6 }), d.topics.infer, 8),
        w('2', examQ(`${d.why[0]}\n\nYou may use the following in your answer:\n- ${d.why[1]}\n- ${d.why[2]}\n\nYou **must** also use information of your own.`, 12, ED_WHY(d.why[3]), { meta: 'Question 2 · AO1, AO2', time: 18 }), d.topics.why, 20),
      ], d.srcA),
      sec('Section B', 'Answer Questions 3(a), (b), (c) and (d). You should spend about 60 minutes on this section. Spelling, punctuation, grammar and specialist terminology are assessed in Question 3(d).', [
        w('3(a)', examQ(`Study Sources B and C.\n\nHow useful are Sources B and C for an enquiry into ${d.enquiry}?\n\nExplain your answer, using Sources B and C and your knowledge of the historical context.`, 8, ED_USE(d.useInd), { meta: 'Question 3(a) · AO3', time: 12 }), d.topics.s),
        w('3(b)', examQ(`Study Interpretations 1 and 2. They give different views about ${d.view}.\n\nWhat is the main difference between these views?\n\nExplain your answer, using details from both interpretations.`, 4, ED_DIFF(d.diffInd), { meta: 'Question 3(b) · AO4', time: 6 }), d.topics.s, 8),
        w('3(c)', examQ(`Suggest **one** reason why Interpretations 1 and 2 give different views about ${d.view}.\n\nYou may use Sources B and C to help explain your answer.`, 4, ED_WHYDIFF(d.whyInd), { meta: 'Question 3(c) · AO4', time: 6 }), d.topics.s, 8),
        w('3(d)', examQ(`How far do you agree with Interpretation 2 about ${d.view}?\n\nExplain your answer, using both interpretations and your knowledge of the historical context.`, 20, ED_INTERP(d.agreeInd), { meta: 'Question 3(d) · AO4 (16 marks) + SPaG (4 marks)', time: 30 }), d.topics.s, 30),
      ], `${d.srcB}\n\n${d.srcC}\n\n---\n\n${d.i1}\n\n${d.i2}`),
    ],
  };
}

// =============================== AQA PAPER 1: Germany 1890-1945 + Conflict and tension 1918-39 ===============================
interface AqP1 {
  iA: string; iB: string; about: string; diffInd: string; whyInd: string; convInd: string;
  desc: [string, string]; ways: [string, string]; imp: [string, string, string, string];
  srcA: string; srcAQ: string; srcAInd: string; srcB: string; srcC: string; useAbout: string; useInd: string; acc: [string, string]; essay: [string, string];
  topics: { interp: string; desc: string; ways: string; imp: string; b1: string; b2: string; acc: string; essay: string };
}
const AQ1: AqP1[] = [
  {
    iA: `**Interpretation A** – from a book about the Weimar Republic written in 2012 by a German historian (practice interpretation written for this app).\n\n> The years 1924 to 1929 were a genuine recovery. The currency was stable, industry was growing and Germany was welcomed back into the community of nations. For a few years Berlin was the most exciting city in Europe, and democracy seemed to have put down roots.`,
    iB: `**Interpretation B** – from a memoir written in 1960 by a man who was a farmer in Bavaria in the 1920s (practice interpretation written for this app).\n\n> We heard about the dancing in Berlin, but it never reached us. Prices for our crops fell year after year and many farms were in debt. The government seemed to care only for the cities. When the Depression came we were already ruined.`,
    about: 'the Weimar Republic in the years 1924-29',
    diffInd: 'Interpretation A says the period was a real recovery - stable currency, growing industry, international acceptance, democracy taking root; Interpretation B says the recovery did not reach farmers - falling prices, debt, neglect by the government.',
    whyInd: 'Interpretation A is a historian writing in 2012 with hindsight and access to national evidence (economic statistics, foreign policy); Interpretation B is a personal memoir of a Bavarian farmer, based on his own experience in the countryside, written after the Nazi period.',
    convInd: 'Interpretation A is supported by: the Rentenmark and end of hyperinflation, the Dawes Plan (1924) and US loans, the Locarno Treaties (1925), joining the League of Nations (1926), cultural flowering; but recovery depended on American loans. Interpretation B is supported by: the agricultural depression from the mid-1920s, farmers\' debts, rising support for extremists in rural areas, the recovery being fragile and uneven. Judgement based on own knowledge.',
    desc: ['Describe **two** problems faced by Kaiser Wilhelm II in ruling Germany before 1914.', 'The growth of socialism - the SPD became the largest party in the Reichstag (1912); the Reichstag had to approve the budget, e.g. for naval expansion; Prussian militarism vs demands for democracy; industrialisation created a large working class with demands for better conditions; the cost of the naval race with Britain (Navy Laws).'],
    ways: ['In what ways were the lives of people in Germany affected by the First World War? Explain your answer.', 'Food shortages caused by the British naval blockade - the "turnip winter" of 1916-17; about 750,000 civilians died from malnutrition and disease; women worked in factories; war widows and orphans; strikes and unrest; the Kiel mutiny and revolution (1918); defeat and the Kaiser\'s abdication; bitterness and the "stab in the back" myth.'],
    imp: ['Which of the following was the more important reason why Hitler became Chancellor in January 1933:', 'the economic depression', 'the political deals of 1932-33 (von Papen and Hindenburg)', 'Depression: unemployment of about 6 million, weak governments and rule by Article 48; Nazi seats rose to 230 (July 1932). Political deals: the Nazis lost seats in November 1932 (196); von Papen persuaded Hindenburg to appoint Hitler, believing he could control him; Schleicher\'s failure; Hindenburg\'s dislike of Hitler. Judgement: the Depression made the Nazis the largest party, but backstairs intrigue made Hitler Chancellor.'],
    srcA: P('Source A', 'from *Deutsche Zeitung*, a German newspaper, published on the day the Treaty of Versailles was signed, 28 June 1919.', `Vengeance! German nation! Today in the Hall of Mirrors the disgraceful treaty is being signed. Do not forget it! The German people will, with unceasing labour, press forward to reconquer the place among the nations to which it is entitled. Then will come vengeance for the shame of 1919.`, true),
    srcAQ: 'Source A opposes the Treaty of Versailles. How do you know?\n\nExplain your answer using Source A and your contextual knowledge.',
    srcAInd: 'Content: "disgraceful treaty", "shame of 1919", "vengeance". Provenance: a German newspaper on the day of signing - reflects German anger. Context: the treaty was a diktat (Germany was not allowed to negotiate); war guilt (Article 231); reparations (£6.6 billion, 1921); loss of land (Alsace-Lorraine, the Polish Corridor) and colonies; army limited to 100,000.',
    srcB: P('Source B', 'from a speech by a French politician to the French parliament in 1919.', `France has lost one and a half million of her sons. Her northern provinces are a desert of ruins. The treaty is too gentle. Germany keeps her unity and her industry; in twenty years she will be ready to strike again. We have not made France safe.`),
    srcC: P('Source C', 'from *The Economic Consequences of the Peace* by J.M. Keynes, a British economist who had been an adviser at the Paris Peace Conference, published in 1919.', `The policy of reducing Germany to servitude for a generation, of degrading the lives of millions of human beings, and of depriving a whole nation of happiness should be abhorrent and detestable.`, true),
    useAbout: 'reactions to the Treaty of Versailles',
    useInd: 'Source B: useful for French anger that the treaty was too lenient - provenance: a French politician speaking to parliament in 1919, reflecting Clemenceau\'s pressure and French public opinion; context: French losses, devastation of northern France, demands for security (demilitarised Rhineland). Source C: useful for British criticism that the treaty was too harsh - Keynes had been at the conference as a Treasury adviser and resigned in protest; an economist\'s view written to influence public opinion, and very influential in Britain and the USA. Context: Lloyd George\'s compromise position; Wilson\'s Fourteen Points; German reactions. Together they show the treaty satisfied no one.',
    acc: ['Write an account of how the Abyssinian Crisis (1935-36) weakened the League of Nations.', 'Mussolini invaded Abyssinia in October 1935; Haile Selassie appealed to the League; sanctions were imposed but excluded oil, and Britain did not close the Suez Canal; the Hoare-Laval Pact (December 1935) secretly offered Italy much of Abyssinia - leaked and caused outrage; Italy completed the conquest (May 1936) and left the League (1937); Hitler remilitarised the Rhineland (March 1936) while attention was on Abyssinia; the League was shown to be powerless; Italy moved closer to Germany (Rome-Berlin Axis, 1936).'],
    essay: ['\'The main reason for the outbreak of war in 1939 was the policy of appeasement.\'\n\nHow far do you agree with this statement? Explain your answer.', 'Appeasement: allowed rearmament, the Rhineland (1936), Anschluss (1938) and Munich (1938) - encouraging Hitler. Other factors: Hitler\'s aims (Lebensraum, overturning Versailles); the Nazi-Soviet Pact (August 1939) removed the threat of a two-front war; the failure of the League of Nations; the Treaty of Versailles creating resentment; the invasion of Czechoslovakia (March 1939) ending appeasement; the British guarantee to Poland. Substantiated judgement.'],
    topics: { interp: 'aqa-ger-weimar', desc: 'aqa-ger-kaiser', ways: 'aqa-ger-kaiser', imp: 'aqa-ger-rise', b1: 'aqa-ct-peace', b2: 'aqa-ct-peace', acc: 'aqa-ct-league', essay: 'aqa-ct-origins' },
  },
  {
    iA: `**Interpretation A** – from a history of Nazi Germany written in 2010 (practice interpretation written for this app).\n\n> The Nazis kept control above all through terror. The Gestapo, the SS and the concentration camps made open opposition almost impossible. Germans conformed because they knew what would happen to them if they did not.`,
    iB: `**Interpretation B** – from a study of public opinion in the Third Reich written in 2014 (practice interpretation written for this app).\n\n> Most Germans did not need to be terrorised. They approved of the jobs, the order on the streets and the return of national pride. The Gestapo was small and relied on ordinary people volunteering information. The regime rested on consent as much as fear.`,
    about: 'how the Nazis kept control of Germany',
    diffInd: 'Interpretation A says the Nazis kept control mainly through terror and fear (Gestapo, SS, camps); Interpretation B says control rested mainly on consent - Germans approved of Nazi achievements, and terror depended on ordinary people informing.',
    whyInd: 'They focus on different evidence: A on the institutions of terror; B on public opinion research (e.g. denunciations to the Gestapo, SPD reports, later surveys). They were written at different times, as historians\' views developed to emphasise popular consent.',
    convInd: 'A supported by: the SS under Himmler, the Gestapo, concentration camps (Dachau 1933), the Night of the Long Knives (1934), the treatment of opponents. B supported by: falling unemployment, propaganda and popular policies, the Gestapo\'s small size and reliance on denunciations, election/plebiscite support, little opposition from most people. Judgement using own knowledge.',
    desc: ['Describe **two** problems the Weimar Republic faced from political extremists in the years 1919-23.', 'The Spartacist uprising (January 1919) - communists tried to seize power in Berlin and were crushed by the Freikorps; the Kapp Putsch (1920) - right-wing Freikorps seized Berlin and the army refused to act, defeated by a general strike; political assassinations, e.g. Erzberger (1921) and Rathenau (1922); the Munich Putsch (1923).'],
    ways: ['In what ways were the lives of young people in Germany affected by Nazi policies? Explain your answer.', 'The Hitler Youth and League of German Maidens - membership compulsory from 1936/1939; military training for boys, preparation for motherhood for girls; the school curriculum changed - race studies, history rewritten, more PE; teachers had to join the Nazi Teachers\' League; textbooks rewritten; some rejected the movement (Edelweiss Pirates, Swing Youth); less time with families.'],
    imp: ['Which of the following was the more important reason why the Nazis were able to control Germany in the years 1933-39:', 'the police state (the SS and Gestapo)', 'propaganda', 'Police state: SS and Gestapo, concentration camps, informers, courts under Nazi control; fear stopped opposition. Propaganda: Goebbels\' Ministry; radio (cheap People\'s Receivers), rallies (Nuremberg), the 1936 Olympics, censorship; built consent and the Hitler myth. Judgement - they worked together: terror for opponents, propaganda for the majority.'],
    srcA: P('Source A', 'from a Japanese newspaper, published in 1932.', `The Lytton Commission has come to Manchuria from Geneva, months after the event, and will write its report at leisure. Meanwhile Japan has brought order to a land of bandits and chaos. Japan will not be lectured by nations who built their own empires by the sword.`),
    srcAQ: 'Source A opposes the League of Nations\' actions over Manchuria. How do you know?\n\nExplain your answer using Source A and your contextual knowledge.',
    srcAInd: 'Content: mocks the slow League ("months after the event", "at leisure"), defends Japan\'s actions, accuses other powers of hypocrisy. Provenance: a Japanese newspaper in 1932 supporting Japanese expansion. Context: the Mukden Incident (September 1931); Japan\'s invasion of Manchuria and creation of Manchukuo; the Lytton Report (1932) condemned Japan; Japan left the League (1933).',
    srcB: P('Source B', 'from statements by the British Prime Minister, Neville Chamberlain, on his return from Munich, 30 September 1938.', `We regard the agreement signed last night ... as symbolic of the desire of our two peoples never to go to war with one another again. ... I believe it is peace for our time. ... Go home and get a nice quiet sleep.`, true),
    srcC: P('Source C', 'from a speech by Winston Churchill, then a backbench MP, in the House of Commons, 5 October 1938.', `We have sustained a total and unmitigated defeat. ... And do not suppose that this is the end. This is only the beginning of the reckoning.`, true),
    useAbout: 'British attitudes towards the Munich Agreement',
    useInd: 'Source B: useful for the Prime Minister\'s view and the relief felt by many Britons - provenance: Chamberlain, defending his own policy, speaking publicly on his return; context: crowds welcomed him; Britain was not ready for war; many saw Versailles as unfair to Germany. Source C: useful for opposition to appeasement - provenance: Churchill, a long-standing critic of appeasement, in a Commons debate with a few days\' reflection - his view was unpopular at the time; context: the Sudetenland handed over; the Czechs were not consulted; Hitler took the rest of Czechoslovakia in March 1939. Together they show divided opinion.',
    acc: ['Write an account of how events in the Rhineland (1936) and Austria (1938) increased international tension.', 'March 1936: German troops entered the demilitarised Rhineland, breaking Versailles and Locarno; Britain and France did nothing (France had an election, Britain thought Germany was "walking into its own back garden"); Hitler grew more confident. March 1938: Anschluss - Schuschnigg\'s planned plebiscite, German troops entered Austria, a 99% yes vote in a Nazi-run plebiscite; again no action; Czechoslovakia was surrounded on three sides, leading to the Sudeten crisis.'],
    essay: ['\'The main reason for the failure of the League of Nations was the absence of the USA.\'\n\nHow far do you agree with this statement? Explain your answer.', 'USA absent: the most powerful nation never joined (Senate rejected the treaty, isolationism), weakening economic sanctions. Other reasons: no army of its own; decisions needed unanimity and were slow; Britain and France put their own interests first (Hoare-Laval); the Depression encouraged aggressive nationalism; Manchuria and Abyssinia; Germany, Japan and Italy left; Germany and the USSR were excluded at first. Substantiated judgement.'],
    topics: { interp: 'aqa-ger-control', desc: 'aqa-ger-weimar', ways: 'aqa-ger-life', imp: 'aqa-ger-control', b1: 'aqa-ct-league', b2: 'aqa-ct-origins', acc: 'aqa-ct-origins', essay: 'aqa-ct-league' },
  },
  {
    iA: `**Interpretation A** – from a textbook about Germany written in 2007 (practice interpretation written for this app).\n\n> The Nazi economic recovery was impressive. Within four years unemployment had almost disappeared. Motorways were built, factories reopened and Germany was strong again. To many Germans it seemed like an economic miracle.`,
    iB: `**Interpretation B** – from a book on the Nazi economy written in 2019 (practice interpretation written for this app).\n\n> The "miracle" was built on rearmament and debt. Women and Jews were removed from the unemployment figures, wages were held down and consumer goods were scarce. By 1939 the economy could only survive by conquering other countries' resources.`,
    about: 'the success of Nazi economic policies',
    diffInd: 'Interpretation A says Nazi economic policy was a success - unemployment disappeared, motorways and factories, strength; Interpretation B says the success was misleading - based on rearmament and debt, hidden unemployment, low wages, and unsustainable without conquest.',
    whyInd: 'A focuses on visible achievements and how Germans felt at the time; B uses later economic evidence (government debt, statistics on wages and consumer goods) with more hindsight about the war.',
    convInd: 'A: unemployment fell from about 6 million (1933) to about 0.3 million (1939); the National Labour Service (RAD), autobahns, rearmament creating jobs; KdF. B: "invisible unemployment" - women and Jews removed from the figures; conscription from 1935; the Four-Year Plan (1936) and autarky failing; "guns or butter" - shortages; Schacht\'s Mefo bills and debt. Judgement.',
    desc: ['Describe **two** ways in which the Nazis persecuted Jewish people in the years 1933-39.', 'The boycott of Jewish shops and businesses (April 1933); Jews banned from the civil service and professions; the Nuremberg Laws (1935) removed citizenship and banned marriage between Jews and non-Jews; Kristallnacht (9-10 November 1938) - synagogues and shops attacked, about 91 Jews killed and 30,000 sent to camps; Jewish children expelled from German schools (1938).'],
    ways: ['In what ways were the lives of German civilians affected by the Second World War? Explain your answer.', 'Rationing from 1939; "total war" from 1943 (Goebbels\' speech) - longer hours, closure of non-essential businesses; women increasingly worked; Allied bombing (e.g. Hamburg 1943, Dresden 1945) killed hundreds of thousands and made many homeless; evacuation of children; foreign forced labourers; the Volkssturm (1944) called up old men and boys; shortages, refugees and defeat in 1945.'],
    imp: ['Which of the following was the more important reason for the rise in support for the Nazis in the years 1929-32:', 'unemployment', 'Hitler\'s leadership and propaganda', 'Unemployment: about 6 million by 1932; the Weimar government seemed helpless; the unemployed and those afraid of losing jobs turned to extremes. Leadership/propaganda: Hitler\'s speeches and "Hitler over Germany" flights; Goebbels\' targeted messages; the SA as a symbol of order; promises to every group. Judgement.'],
    srcA: P('Source A', 'from a Soviet newspaper, August 1939.', `The pact signed in Moscow is a victory for peace. The Soviet Union will not allow itself to be dragged into a war started by others. While Britain and France talked and delayed, the Soviet government has acted to protect the security of the Soviet people.`),
    srcAQ: 'Source A supports the Nazi-Soviet Pact. How do you know?\n\nExplain your answer using Source A and your contextual knowledge.',
    srcAInd: 'Content: "a victory for peace", protects Soviet security, blames Britain and France for delay. Provenance: a Soviet newspaper, controlled by Stalin\'s government, justifying the policy. Context: the Nazi-Soviet Pact (23 August 1939); Stalin distrusted Britain and France after Munich; slow British negotiations; the secret clause to divide Poland; time to build up Soviet defences.',
    srcB: P('Source B', 'from the memoirs of a British diplomat who took part in the talks with the Soviet Union in August 1939, published in 1950.', `We were sent to Moscow by slow boat, with no power to sign anything. The Russians asked if we could guarantee that Poland would let the Red Army through. We could not. A few days later Ribbentrop flew in and signed in a single afternoon.`),
    srcC: P('Source C', 'from notes of a speech by Hitler to his generals at Obersalzberg, 22 August 1939.', `Our enemies are small fry. I saw them at Munich. ... Now Poland is in the position in which I wanted her.`, true),
    useAbout: 'why the Nazi-Soviet Pact was signed in 1939',
    useInd: 'Source B: useful for why the USSR turned to Germany - British negotiations were slow and half-hearted, and the Poles refused to let the Red Army in; provenance: a participant writing later, possibly defending himself or criticising his government. Source C: useful for Hitler\'s reasons - avoiding a two-front war and isolating Poland - and his contempt for Britain and France after Munich; provenance: notes of a private speech to his generals, so it reveals intentions, though the notes were taken by listeners. Context: Munich (USSR excluded), Stalin\'s fear of German attack, the secret protocol dividing Poland, the invasion of Poland on 1 September 1939.',
    acc: ['Write an account of how the Manchurian Crisis (1931-33) affected the League of Nations.', 'September 1931 Mukden Incident; Japan invaded Manchuria; China appealed to the League; the League sent the Lytton Commission, which took a year to report; the report (1932) condemned Japan and called for withdrawal; Japan ignored it and left the League (March 1933); no sanctions because Britain and France did not want to harm trade or risk war, and the USA was not a member; Japan went on to attack China (1937); the League\'s weakness encouraged Mussolini and Hitler.'],
    essay: ['\'The Treaty of Versailles was fair to Germany.\'\n\nHow far do you agree with this statement? Explain your answer.', 'Fair: Germany had imposed a harsher treaty on Russia (Brest-Litovsk, 1918); the damage to France and Belgium; reparations were reduced (Dawes, Young Plans); Germany remained united with its industry. Unfair: a diktat - Germany not consulted; war guilt clause (231); reparations of £6.6 billion; loss of 13% of land and all colonies; army limited to 100,000, no air force; the Rhineland demilitarised; self-determination denied to Germans (Anschluss forbidden). Substantiated judgement.'],
    topics: { interp: 'aqa-ger-life', desc: 'aqa-ger-control', ways: 'aqa-ger-war', imp: 'aqa-ger-rise', b1: 'aqa-ct-origins', b2: 'aqa-ct-origins', acc: 'aqa-ct-league', essay: 'aqa-ct-peace' },
  },
];
function aqP1(t: number): MockTest {
  const d = AQ1[t];
  return {
    id: `history-aqa-p1-t${t + 1}`, paperId: 'history-aqa-p1', n: (t + 1) as 1 | 2 | 3, title: `Practice paper ${t + 1}`,
    focus: ['Weimar recovery, the Kaiser, Hitler\'s appointment · Versailles, Abyssinia and appeasement.', 'Nazi control, extremists, young people · Manchuria, Munich and the League\'s failure.', 'The Nazi economy, persecution, the home front · the Nazi-Soviet Pact and whether Versailles was fair.'][t],
    sections: [
      sec('Section A: Germany, 1890-1945: Democracy and dictatorship', 'Answer all questions in this section. You should spend about 50 minutes on this section.', [
        w('01', examQ(`Read Interpretations A and B.\n\nHow does Interpretation B differ from Interpretation A about ${d.about}?\n\nExplain your answer using Interpretations A and B.`, 4, A4('Developed analysis of how the interpretations differ in content, supported by detail from both.', 'Simple analysis of difference based on content.', d.diffInd), { meta: 'Question 01 · AO4', time: 5 }), d.topics.interp, 8),
        w('02', examQ(`Why might the authors of Interpretations A and B have a different interpretation about ${d.about}?\n\nExplain your answer using Interpretations A and B and your contextual knowledge.`, 4, A4('Developed explanation of why the interpretations differ, based on their provenance (who wrote them, when, why, with what evidence).', 'Simple explanation of a reason for the difference.', d.whyInd), { meta: 'Question 02 · AO4', time: 5 }), d.topics.interp, 8),
        w('03', examQ(`Which interpretation gives the more convincing opinion about ${d.about}?\n\nExplain your answer based on your contextual knowledge and what Interpretations A and B say.`, 8, A8(['Complex evaluation of both interpretations, using contextual knowledge to judge which is more convincing; a sustained judgement.', 'Developed evaluation of both interpretations with contextual knowledge.', 'Simple evaluation of one or both interpretations.', 'Basic analysis of one or both interpretations.'], d.convInd), { meta: 'Question 03 · AO4', time: 10 }), d.topics.interp),
        w('04', examQ(d.desc[0], 4, A4('Complex description of two features, each supported by specific knowledge.', 'Basic description of one or more features.', d.desc[1]), { meta: 'Question 04 · AO1', time: 5 }), d.topics.desc, 8),
        w('05', examQ(d.ways[0], 8, A8(['Complex explanation of changes/effects, sustained and supported by a range of accurate, relevant knowledge.', 'Developed explanation of two or more ways, supported by accurate knowledge.', 'Simple explanation of one way.', 'Basic explanation; limited knowledge.'], d.ways[1]), { meta: 'Question 05 · AO1, AO2', time: 10 }), d.topics.ways),
        w('06', examQ(`${d.imp[0]}\n- ${d.imp[1]}\n- ${d.imp[2]}\n\nExplain your answer with reference to both bullet points.`, 12, A12(['Complex explanation of both bullet points with a sustained judgement of which is more important, supported by a range of accurate knowledge.', 'Developed explanation of both bullet points.', 'Simple explanation of one or both bullet points.', 'Basic explanation of one or both bullet points.'], d.imp[3]), { meta: 'Question 06 · AO1, AO2', time: 15 }), d.topics.imp, 20),
      ], `${d.iA}\n\n${d.iB}`),
      sec('Section B: Conflict and tension, 1918-1939', 'Answer all questions in this section. You should spend about 60 minutes on this section. Spelling, punctuation, grammar and specialist terminology are assessed in Question 10 (4 marks).', [
        w('07', examQ(`Study Source A.\n\n${d.srcAQ}`, 4, A4('Developed analysis of the source based on content and/or provenance, supported by contextual knowledge.', 'Simple analysis based on content and/or provenance.', d.srcAInd), { meta: 'Question 07 · AO3', time: 5 }), d.topics.b1, 8),
        w('08', examQ(`Study Sources B and C.\n\nHow useful are Sources B and C to a historian studying ${d.useAbout}?\n\nExplain your answer using Sources B and C and your contextual knowledge.`, 12, A12(['Complex evaluation of both sources with sustained judgement, based on content and provenance and supported by contextual knowledge.', 'Developed evaluation of both sources based on content and/or provenance, with contextual knowledge.', 'Simple evaluation of one or both sources.', 'Basic analysis of one or both sources.'], d.useInd), { meta: 'Question 08 · AO3', time: 15 }), d.topics.b2, 20),
        w('09', examQ(d.acc[0], 8, A8(['Complex analytical narrative showing how events led to the outcome (causation/consequence), with a range of accurate knowledge.', 'Developed narrative with links between events.', 'Simple narrative of events.', 'Basic narrative.'], d.acc[1]), { meta: 'Question 09 · AO1, AO2', time: 12 }), d.topics.acc),
        w('10', examQ(d.essay[0], 20, A16(d.essay[1], true), { meta: 'Question 10 · AO1, AO2 (16 marks) + SPaG (4 marks)', time: 25 }), d.topics.essay, 30),
      ], `${d.srcA}\n\n${d.srcB}\n\n${d.srcC}`),
    ],
  };
}

// =============================== AQA PAPER 2: Health and the people + Elizabethan England ===============================
interface AqP2 {
  srcA: string; useAbout: string; useInd: string; sig: [string, string]; sim: [string, string]; factor: [string, string];
  iA: string; convAbout: string; convInd: string; imp: [string, string]; acc: [string, string]; site: [string, string, string];
  topics: { use: string; sig: string; sim: string; factor: string; conv: string; imp: string; acc: string; site: string };
}
const AQ2: AqP2[] = [
  {
    srcA: P('Source A', 'from a London newspaper, June 1858.', `The Thames has become a sewer. In this heat the smell is so dreadful that the members of Parliament have hung curtains soaked in chloride of lime across the windows of their Committee rooms, and some talk of leaving Westminster altogether. Yet the poor of Southwark and Lambeth have breathed this air and drunk this water for years without anyone in Parliament troubling to notice.`),
    useAbout: 'public health in nineteenth-century London',
    useInd: 'Content: the "Great Stink" of 1858; the Thames used as a sewer; MPs affected directly; the poor had suffered for years. Provenance: a newspaper written at the time, criticising Parliament - shows public pressure. Context: cholera epidemics (1832, 1848-49, 1854); belief in miasma; Snow\'s work (1854) not yet widely accepted; Bazalgette\'s sewer system approved soon after (1859-75); laissez-faire attitudes; the 1875 Public Health Act.',
    sig: ['Explain the significance of the discovery and development of penicillin for the treatment of disease.', 'The first antibiotic - could cure bacterial infections that killed millions (e.g. septicaemia, pneumonia); Fleming (1928), Florey and Chain (1940-41); mass production in the Second World War saved many wounded soldiers; led to the development of other antibiotics; long-term problems - antibiotic resistance and MRSA; significance measured by lives saved and lasting impact.'],
    sim: ['Compare the Black Death (1348-49) and the Great Plague (1665). In what ways were the responses to them similar?\n\nExplain your answer with reference to both outbreaks.', 'In both, people blamed God and miasma and responded with prayer, fasting and flagellation (1348) or religious services (1665); both used herbs, posies and fires to clear bad air; local authorities tried to control spread (1348 limited; 1665 plague orders - houses shut up, red crosses, searchers of the dead); people fled towns; neither understood that fleas on rats spread the disease; little government co-ordination nationally.'],
    factor: ['Has war been the main factor in the development of medicine in Britain since medieval times?\n\nExplain your answer with reference to war and other factors.\n\nUse a range of examples from across your study of Health and the people: c1000 to the present day.', 'War: medieval surgeons learned on the battlefield (John of Arderne); Paré\'s ligatures (French but influential); the Crimean War and Nightingale\'s nursing reforms; the First World War - blood transfusion, X-rays, plastic surgery (Gillies); the Second World War - mass production of penicillin, skin grafts (McIndoe), the Beveridge Report leading to the NHS. Other factors: science and technology (microscopes, germ theory), individuals (Vesalius, Harvey, Jenner, Pasteur, Lister), government (Public Health Acts, NHS), the Church (held back progress in medieval times), communication (printing press). Substantiated judgement.'],
    iA: `**Interpretation A** – from a biography of Elizabeth I written in 2015 (practice interpretation written for this app).\n\n> Elizabeth handled Parliament with great skill. She flattered it, scolded it and, when necessary, gave way gracefully, as she did over monopolies in 1601. Her "Golden Speech" left MPs in tears. No monarch understood better how to manage the men who granted her money.`,
    convAbout: 'Elizabeth\'s relationship with Parliament',
    convInd: 'Convincing: Elizabeth controlled when Parliament met (only 13 sessions in 45 years); she used the Privy Council and Speaker to manage business; she gave way over monopolies in 1601 and her Golden Speech was well received. Less convincing: there were conflicts - over marriage and succession (1566), Peter Wentworth\'s demands for free speech (1576, 1587 - imprisoned), Puritan attempts to change the Church (Strickland, Cope\'s Bill and Book), and anger at monopolies; her refusal to name an heir. Judgement.',
    imp: ['Explain what was important about the Poor Law of 1601.', 'It brought together earlier laws into a national system that lasted for over 200 years; each parish had to appoint overseers of the poor and collect a compulsory poor rate; it distinguished between the "deserving" poor (old, sick, children), the able-bodied poor (given work) and the idle poor (punished); poor children were apprenticed; it reflected concern about vagrancy and disorder; it made the government responsible for poverty.'],
    acc: ['Write an account of the ways in which the Spanish Armada was defeated in 1588.', 'English ships were faster and more manoeuvrable, with long-range guns; the Spanish sailed in a crescent formation up the Channel; skirmishes off Plymouth and the Isle of Wight; the Spanish anchored at Calais to wait for Parma, who was not ready; English fireships at night forced them to cut anchors and scatter; the Battle of Gravelines (8 August) - English ships attacked at close range; the "Protestant wind" blew the Spanish into the North Sea; storms off Scotland and Ireland wrecked many ships; poor Spanish leadership and supplies (Medina Sidonia, rotten barrels).'],
    site: ['Hardwick Hall', '\'The main reason Hardwick Hall was built was to show off Bess of Hardwick\'s wealth and status.\'', 'For: built 1590-97 for Bess of Hardwick (Countess of Shrewsbury), one of the richest women in England; huge windows ("more glass than wall") when glass was very expensive; Bess\'s initials ES on the rooftop towers; tapestries, the High Great Chamber and Long Gallery to impress visitors; symmetrical "prodigy house" design by Robert Smythson. Other purposes: comfortable living and fashion - Renaissance architecture; a home for her granddaughter Arbella Stuart, a possible heir to the throne; suitable for a royal visit; built after her separation from her husband; reflects the Elizabethan "Golden Age" of building by the newly rich. Judgement using the site and context.'],
    topics: { use: 'aqa-med-c18-19', sig: 'aqa-med-modern', sim: 'aqa-med-medieval', factor: 'aqa-med-modern', conv: 'aqa-eliz-gov', imp: 'aqa-eliz-society', acc: 'aqa-eliz-spain', site: 'aqa-eliz-society' },
  },
  {
    srcA: P('Source A', 'from a letter written by a surgeon at the Glasgow Royal Infirmary, 1869.', `Since Mr Lister began to use his carbolic acid in the wards, the change is remarkable. Wounds that once became putrid now heal cleanly, and amputations that ended in death from hospital gangrene are survived. Many of my colleagues sneer at "Lister's spray" and say it slows the work. But they have not seen these wards before and after.`),
    useAbout: 'the impact of antiseptics on surgery',
    useInd: 'Content: carbolic acid reduced infection and deaths after surgery; opposition from other surgeons. Provenance: a surgeon at Lister\'s own hospital, an eyewitness at the time, perhaps biased in Lister\'s favour. Context: Lister began using carbolic acid in 1865 and published in 1867, inspired by Pasteur\'s germ theory; his death rate after amputation fell from about 46% to about 15%; opposition - the spray was unpleasant and slowed operations, and many did not accept germ theory; aseptic surgery replaced antiseptic surgery by the 1890s.',
    sig: ['Explain the significance of Edward Jenner\'s work on vaccination.', 'Jenner (1796) showed cowpox protected against smallpox, based on observation and experiment; safer than inoculation; spread worldwide; the government made vaccination compulsory (1853) - an early example of government intervention in health; opposition (Anti-Vaccination League) showed attitudes slowed change; Jenner did not know why it worked - it took Pasteur to develop vaccines for other diseases; smallpox was eventually eradicated worldwide (1980).'],
    sim: ['Compare the work of Vesalius and Harvey. In what ways were they similar?\n\nExplain your answer with reference to both.', 'Both challenged Galen\'s ideas using dissection and observation; both published their findings in books spread by the printing press (Vesalius\'s *Fabric of the Human Body*, 1543; Harvey\'s *An Anatomical Account of the Motion of the Heart and Blood*, 1628); both faced opposition from traditional physicians; both had limited immediate impact on treatment, but improved understanding of anatomy and physiology; both reflect the scientific approach of the Renaissance.'],
    factor: ['Has the role of government been the main factor in the development of public health in Britain since medieval times?\n\nExplain your answer with reference to government and other factors.\n\nUse a range of examples from across your study of Health and the people: c1000 to the present day.', 'Government: medieval town authorities cleaning streets and fining polluters; 1665 plague orders; the 1848 and 1875 Public Health Acts; the Liberal reforms; the NHS (1948); Clean Air Acts; anti-smoking laws (2007). Other factors: science (Snow, Pasteur\'s germ theory), individuals (Chadwick, Bazalgette), war (the Boer War revealed poor health; WW2 and the Beveridge Report), the Church (monasteries\' water supplies), technology (sewers), public pressure and voting reform (1867). Substantiated judgement.'],
    iA: `**Interpretation A** – from a history of Tudor England written in 2011 (practice interpretation written for this app).\n\n> Elizabeth did not want to "make windows into men's souls". She punished Catholics only when they became a political danger. It was the Pope and the plotters, not the Queen, who turned religion into a matter of treason.`,
    convAbout: 'Elizabeth\'s treatment of Catholics',
    convInd: 'Convincing: in the 1560s recusancy fines were low and rarely enforced; Elizabeth wanted outward conformity; harsher laws followed political threats - the Papal Bull (1570), the Ridolfi (1571), Throckmorton (1583) and Babington (1586) plots, the arrival of Jesuit missionaries (1580). Less convincing: increasingly harsh laws (1581 fine of £20, 1585 Act against Jesuits and seminary priests); about 200 Catholics were executed, including priests such as Edmund Campion (1581); priest holes and fear. Judgement.',
    imp: ['Explain what was important about Drake\'s circumnavigation of the globe (1577-80).', 'Drake was the first Englishman to sail around the world, bringing national prestige; he raided Spanish ships and ports, returning with treasure worth more than the Crown\'s annual income; Elizabeth knighted him on board the Golden Hind (1581), angering Spain; it encouraged further exploration and trade; it increased tension with Spain, contributing to war; it showed English naval skill.'],
    acc: ['Write an account of the ways in which Mary, Queen of Scots, threatened Elizabeth.', 'Mary fled to England in 1568 and became a focus for Catholic plots; her claim to the throne as Henry VII\'s great-granddaughter; the Revolt of the Northern Earls (1569) aimed to free her; the Ridolfi Plot (1571) with Spain and the Pope; the Throckmorton Plot (1583) with French and Spanish support; the Babington Plot (1586) - her letters were intercepted by Walsingham; she was tried and executed in February 1587, which helped trigger the Armada.'],
    site: ['The Globe Theatre', '\'The main reason for the popularity of the Globe Theatre was that it was cheap to visit.\'', 'Cheap: groundlings paid a penny to stand in the yard, so the poor could attend; for more you could sit in the galleries. Other reasons: the quality of plays by Shakespeare and others; famous actors such as Richard Burbage; the Lord Chamberlain\'s Men had royal and noble support; its location on Bankside, Southwark, outside the City authorities\' control and near other entertainments; its size (about 3,000 people) and design - the stage, galleries, trapdoors and special effects; built in 1599 from the timbers of The Theatre; plays performed in the afternoon in daylight; flags announced performances; opposition from Puritans. Judgement using the site and context.'],
    topics: { use: 'aqa-med-c18-19', sig: 'aqa-med-c18-19', sim: 'aqa-med-renaissance', factor: 'aqa-med-c18-19', conv: 'aqa-eliz-spain', imp: 'aqa-eliz-society', acc: 'aqa-eliz-spain', site: 'aqa-eliz-society' },
  },
  {
    srcA: P('Source A', 'from a leaflet sent to every household in Britain, 1948.', `Your new National Health Service begins on 5th July. It will provide you with all medical, dental and nursing care. Everyone, rich or poor, man, woman or child, can use it. There are no charges, except for a few special items. It is not a "charity". You are all paying for it, mainly as taxpayers.`),
    useAbout: 'the creation of the National Health Service',
    useInd: 'Content: free care for everyone, funded by taxation, available from 5 July 1948. Provenance: an official government leaflet sent to every home - accurately states the aims but is persuasive and does not show problems. (The real 1948 leaflet used very similar words; this version is a practice adaptation.) Context: the Beveridge Report (1942) and the "five giants"; Aneurin Bevan, Minister of Health; opposition from doctors (BMA) until Bevan "stuffed their mouths with gold"; huge demand for glasses and dentures; prescription charges introduced from 1952.',
    sig: ['Explain the significance of John Snow\'s work on cholera.', 'In 1854 Snow mapped deaths around the Broad Street pump in Soho and had the handle removed - cases fell; he showed cholera was spread by contaminated water, challenging miasma; he used statistical evidence; many ignored his ideas at first; after Pasteur\'s germ theory (1861) his work was seen as proof; it supported the case for clean water and sewers (Bazalgette) and the 1875 Public Health Act; an early example of epidemiology.'],
    sim: ['Compare the development of anaesthetics and antiseptics in the nineteenth century. In what ways were they similar?\n\nExplain your answer with reference to both.', 'Both solved one of the three problems of surgery (pain and infection); both were developed by individuals (Simpson\'s chloroform, 1847; Lister\'s carbolic acid, 1865-67) using experiment and observation; both faced opposition from surgeons and the public (religious objections to pain relief; dislike of Lister\'s spray); both initially caused new problems (deaths such as Hannah Greener in 1848; carbolic irritating skin); both led to more ambitious operations; both were eventually improved (safer anaesthetics, aseptic surgery).'],
    factor: ['Has science and technology been the main factor in the development of the treatment of disease in Britain since medieval times?\n\nExplain your answer with reference to science and technology and other factors.\n\nUse a range of examples from across your study of Health and the people: c1000 to the present day.', 'Science and technology: microscopes, germ theory, magic bullets, penicillin, X-rays, transplants, keyhole surgery, DNA and genetic medicine. Other factors: individuals (Fleming, Florey, Chain, Lister), war (WW2 and penicillin production), government (the NHS making treatment available to all), the Church and attitudes slowing change in medieval times, chance (Fleming\'s mould), communication. Substantiated judgement.'],
    iA: `**Interpretation A** – from a book about Elizabeth\'s court written in 2017 (practice interpretation written for this app).\n\n> In the 1590s Elizabeth\'s grip on her court weakened. Her trusted advisers - Leicester, Walsingham, Burghley - had died, and younger men competed fiercely for her favour. The Earl of Essex\'s rebellion in 1601 showed how dangerous these rivalries had become.`,
    convAbout: 'Elizabeth\'s court in the 1590s',
    convInd: 'Convincing: Leicester died in 1588, Walsingham in 1590 and Burghley in 1598; rivalry between Robert Cecil and the Earl of Essex; Essex\'s failure in Ireland (1599), loss of his monopoly on sweet wines, and the rebellion in February 1601 - he was executed. Less convincing: the rebellion failed quickly with little support; Elizabeth still controlled patronage; Robert Cecil managed government effectively and the smooth succession of James VI in 1603. Judgement.',
    imp: ['Explain what was important about the Puritan threat to Elizabeth.', 'Puritans wanted to remove Catholic elements from the Church, challenging the Religious Settlement and Elizabeth\'s authority as Supreme Governor; Puritan MPs (e.g. Peter Wentworth, Anthony Cope) raised religious issues in Parliament; prophesyings and Archbishop Grindal\'s refusal to ban them (he was suspended in 1577); the Marprelate Tracts (1588-89) attacked bishops; Archbishop Whitgift cracked down; separatists were executed (1593 Act against Seditious Sectaries).'],
    acc: ['Write an account of the ways in which Elizabeth dealt with the Catholic threat in the 1580s.', 'Jesuit missionaries arrived from 1580 (Campion executed 1581); the 1581 Act raised recusancy fines to £20 a month and made converting people to Catholicism treason; Walsingham\'s spy network uncovered the Throckmorton Plot (1583); the Spanish ambassador was expelled; the Bond of Association (1584) and the Act for the Preservation of the Queen\'s Safety (1585); the 1585 Act ordered Jesuits and seminary priests to leave; the Babington Plot (1586) and Mary\'s execution (1587); the defeat of the Armada (1588).'],
    site: ['Kenilworth Castle', '\'The main purpose of the entertainments at Kenilworth Castle in 1575 was to persuade Elizabeth to marry Robert Dudley, Earl of Leicester.\'', 'For: Elizabeth stayed for 19 days in July 1575; Leicester spent a fortune on entertainments - fireworks, hunting, bear-baiting, a water pageant with the Lady of the Lake, masques; some performances hinted at marriage (a final masque about marriage was apparently cancelled); he built a new gatehouse, a garden and "Leicester\'s Building" with large windows for her. Other purposes: to show Leicester\'s wealth, status and loyalty and win royal favour and patronage; Elizabethan royal progresses - the monarch was seen by her people, and hosts competed to impress; entertainment and spectacle typical of the Elizabethan court. Judgement using the site and context.'],
    topics: { use: 'aqa-med-modern', sig: 'aqa-med-c18-19', sim: 'aqa-med-c18-19', factor: 'aqa-med-modern', conv: 'aqa-eliz-gov', imp: 'aqa-eliz-spain', acc: 'aqa-eliz-spain', site: 'aqa-eliz-gov' },
  },
];
function aqP2(t: number): MockTest {
  const d = AQ2[t];
  const a8 = (ind: string, desc: [string, string, string, string]) => A8(desc, ind);
  return {
    id: `history-aqa-p2-t${t + 1}`, paperId: 'history-aqa-p2', n: (t + 1) as 1 | 2 | 3, title: `Practice paper ${t + 1}`,
    focus: ['The Great Stink, penicillin, plagues and war · Parliament, the Poor Law, the Armada · site: Hardwick Hall.', 'Lister, Jenner, Vesalius and Harvey, government · Catholics, Drake, Mary, Queen of Scots · site: the Globe.', 'The NHS, Snow, anaesthetics and antiseptics, science · the 1590s court, Puritans, Catholics · site: Kenilworth.'][t],
    sections: [
      sec('Section A: Britain: Health and the people, c1000 to the present day', 'Answer all questions in this section. You should spend about 50 minutes on this section. Spelling, punctuation, grammar and specialist terminology are assessed in Question 04 (4 marks).', [
        w('01', examQ(`Study Source A.\n\nHow useful is Source A to a historian studying ${d.useAbout}?\n\nExplain your answer using Source A and your contextual knowledge.`, 8, a8(d.useInd, ['Complex evaluation of the source based on content and provenance, with sustained judgement supported by contextual knowledge.', 'Developed evaluation based on content and/or provenance, with contextual knowledge.', 'Simple evaluation of the source.', 'Basic analysis of the source.']), { meta: 'Question 01 · AO3', time: 10 }), d.topics.use),
        w('02', examQ(d.sig[0], 8, a8(d.sig[1], ['Complex explanation of significance - short- and long-term, supported by a range of accurate knowledge.', 'Developed explanation of significance.', 'Simple explanation of significance.', 'Basic explanation.']), { meta: 'Question 02 · AO1, AO2', time: 10 }), d.topics.sig),
        w('03', examQ(d.sim[0], 8, a8(d.sim[1], ['Complex explanation of similarities, supported by a range of accurate knowledge of both.', 'Developed explanation of similarities.', 'Simple explanation of a similarity.', 'Basic explanation.']), { meta: 'Question 03 · AO1, AO2', time: 10 }), d.topics.sim),
        w('04', examQ(d.factor[0], 20, A16(d.factor[1], true), { meta: 'Question 04 · AO1, AO2 (16 marks) + SPaG (4 marks)', time: 25 }), d.topics.factor, 30),
      ], d.srcA),
      sec('Section B: Elizabethan England, c1568-1603', `Answer all questions in this section. You should spend about 50 minutes on this section. Question 08 is on the historic environment: in these practice papers the site is **${d.site[0]}**. AQA names a different site each year, so check the site for your exam year with your teacher.`, [
        w('05', examQ(`Read Interpretation A.\n\nHow convincing is Interpretation A about ${d.convAbout}?\n\nExplain your answer based on your contextual knowledge and what it says.`, 8, a8(d.convInd, ['Complex evaluation of the interpretation, testing it against contextual knowledge with a sustained judgement.', 'Developed evaluation of the interpretation with contextual knowledge.', 'Simple evaluation of the interpretation.', 'Basic analysis of the interpretation.']), { meta: 'Question 05 · AO4', time: 10 }), d.topics.conv),
        w('06', examQ(d.imp[0], 8, a8(d.imp[1], ['Complex explanation of importance, supported by a range of accurate knowledge.', 'Developed explanation of importance.', 'Simple explanation.', 'Basic explanation.']), { meta: 'Question 06 · AO1, AO2', time: 10 }), d.topics.imp),
        w('07', examQ(d.acc[0], 8, a8(d.acc[1], ['Complex analytical narrative of the ways, showing causation/consequence, with a range of accurate knowledge.', 'Developed narrative linking events.', 'Simple narrative.', 'Basic narrative.']), { meta: 'Question 07 · AO1, AO2', time: 10 }), d.topics.acc),
        w('08', examQ(`${d.site[1]}\n\nHow far does a study of ${d.site[0]} support this statement?\n\nExplain your answer. You should refer to ${d.site[0]} and your contextual knowledge.`, 16, A16(d.site[2], false), { meta: 'Question 08 · AO1, AO2 (historic environment)', time: 20 }), d.topics.site, 28),
      ], d.iA),
    ],
  };
}

